COURSE.add({
  id: 'm12', order: 12, icon: '🔭',
  title: { en: 'Observability: seeing inside your agent', he: 'Observability: לראות לתוך הסוכן שלך' },
  summary: { en: 'Logs, metrics and traces for models and agents: OpenTelemetry, AgentCore Observability, model invocation logging, dashboards, alarms and a debugging playbook.', he: 'Logs, metrics ו-traces למודלים ולסוכנים: OpenTelemetry, AgentCore Observability, model invocation logging, דשבורדים, alarms ו-playbook לדיבוג.' },
  glossary: [
    { term: 'Observability', aka: ['o11y'], en: 'The ability to understand what a running system is doing from the data it emits: logs, metrics and traces.', he: 'היכולת להבין מה מערכת רצה עושה מתוך המידע שהיא פולטת: logs, metrics ו-traces.' },
    { term: 'Log', aka: ['logs'], en: 'A text record of one event, with a timestamp. Good for details: "what exactly happened here".', he: 'רשומת טקסט של אירוע אחד, עם חותמת זמן. טוב לפרטים: "מה בדיוק קרה כאן".' },
    { term: 'Metric', aka: ['metrics'], en: 'A number measured over time, such as requests per minute or average latency. Good for trends and alarms.', he: 'מספר שנמדד לאורך זמן, כמו בקשות לדקה או latency ממוצע. טוב למגמות ול-alarms.' },
    { term: 'Trace', aka: ['traces', 'tracing'], en: 'The full story of one request: every step it went through, in order, with timings.', he: 'הסיפור המלא של בקשה אחת: כל שלב שהיא עברה, לפי הסדר, עם זמנים.' },
    { term: 'Span', aka: ['spans'], en: 'One step inside a trace: one model call, one tool call, one retrieval. It has a name, a start time, a duration and attributes.', he: 'שלב אחד בתוך trace: קריאה אחת למודל, קריאה אחת לכלי, אחזור אחד. יש לו שם, זמן התחלה, משך ו-attributes.' },
    { term: 'Session', aka: ['sessions'], en: 'One whole conversation between a user and an agent. A session contains many traces, one per turn.', he: 'שיחה שלמה אחת בין משתמש לסוכן. session מכיל הרבה traces, אחד לכל תור.' },
    { term: 'Attribute', aka: ['attributes'], en: 'A key-value pair attached to a span, for example the model name or the number of input tokens.', he: 'זוג מפתח-ערך שמוצמד ל-span, למשל שם המודל או מספר טוקני הקלט.' },
    { term: 'OpenTelemetry', aka: ['OTel', 'OTEL'], en: 'An open, vendor-neutral standard and set of libraries for producing traces, metrics and logs. AgentCore uses its format.', he: 'תקן פתוח ולא תלוי-ספק, יחד עם ספריות, לייצור traces, metrics ו-logs. AgentCore משתמש בפורמט שלו.' },
    { term: 'Instrumentation', aka: ['instrument', 'instrumented'], en: 'Code that produces telemetry. Auto-instrumentation adds it for you by wrapping known libraries, without changing your code.', he: 'קוד שמייצר טלמטריה. Auto-instrumentation מוסיף אותו בשבילך על ידי עטיפה של ספריות מוכרות, בלי לשנות את הקוד שלך.' },
    { term: 'ADOT', aka: ['AWS Distro for OpenTelemetry'], en: 'AWS Distro for OpenTelemetry. The AWS-supported build of OpenTelemetry that sends data to CloudWatch. Python package: aws-opentelemetry-distro.', he: 'AWS Distro for OpenTelemetry. הגרסה של OpenTelemetry ש-AWS תומכת בה, ששולחת מידע ל-CloudWatch. חבילת Python: aws-opentelemetry-distro.' },
    { term: 'GenAI semantic conventions', aka: ['semantic conventions', 'semconv'], en: 'Agreed attribute names for AI telemetry (such as gen_ai.usage.input_tokens), so every tool reads the same data the same way.', he: 'שמות attributes מוסכמים לטלמטריה של AI (כמו gen_ai.usage.input_tokens), כדי שכל כלי יקרא את אותו מידע באותה צורה.' },
    { term: 'Telemetry', en: 'The data a system sends out about itself: logs, metrics and traces together.', he: 'המידע שמערכת שולחת על עצמה: logs, metrics ו-traces יחד.' },
    { term: 'CloudWatch', aka: ['Amazon CloudWatch'], en: 'The AWS monitoring service. It stores logs and metrics, draws dashboards and fires alarms.', he: 'שירות הניטור של AWS. שומר logs ו-metrics, מצייר דשבורדים ומפעיל alarms.' },
    { term: 'Log group', aka: ['log groups'], en: 'A named container of logs in CloudWatch, usually one per application or resource. Retention and access are set on it.', he: 'מיכל logs עם שם ב-CloudWatch, בדרך כלל אחד לכל אפליקציה או משאב. עליו מגדירים retention והרשאות.' },
    { term: 'Log stream', aka: ['log streams'], en: 'One sequence of log events inside a log group, usually from one source.', he: 'רצף אחד של אירועי log בתוך log group, בדרך כלל ממקור אחד.' },
    { term: 'Transaction Search', en: 'A CloudWatch feature that stores spans as structured logs so you can search every trace. You enable it once per account for AgentCore traces.', he: 'יכולת של CloudWatch ששומרת spans כ-logs מובנים כדי שאפשר יהיה לחפש בכל trace. מפעילים אותה פעם אחת לחשבון בשביל traces של AgentCore.' },
    { term: 'Model invocation logging', aka: ['invocation logging', 'invocation logs'], en: 'A Bedrock setting (off by default) that saves the full request, response and metadata of model calls to CloudWatch Logs or S3.', he: 'הגדרה ב-Bedrock (כבויה כברירת מחדל) ששומרת את הבקשה, התשובה וה-metadata המלאים של קריאות למודל ב-CloudWatch Logs או ב-S3.' },
    { term: 'CloudTrail', aka: ['AWS CloudTrail'], en: 'The AWS audit log. It records who called which AWS API, when and from where. It does not record prompt text.', he: 'יומן הביקורת של AWS. רושם מי קרא לאיזה API של AWS, מתי ומאיפה. הוא לא רושם את טקסט הפרומפט.' },
    { term: 'Namespace', en: 'A folder name for CloudWatch metrics. Bedrock model metrics live in AWS/Bedrock.', he: 'שם תיקייה ל-metrics ב-CloudWatch. ה-metrics של מודלי Bedrock נמצאים ב-AWS/Bedrock.' },
    { term: 'Dimension', aka: ['dimensions'], en: 'A label on a metric that lets you slice it, for example ModelId.', he: 'תווית על metric שמאפשרת לפלח אותו, למשל ModelId.' },
    { term: 'Percentile', aka: ['p50', 'p95', 'p99'], en: 'p95 = the value that 95% of requests are faster than. It shows what your slowest users feel, which an average hides.', he: 'p95 = הערך ש-95% מהבקשות מהירות ממנו. מראה מה המשתמשים הכי איטיים מרגישים, דבר שממוצע מסתיר.' },
    { term: 'Alarm', aka: ['alarms'], en: 'A CloudWatch rule that watches a metric and notifies you when it crosses a threshold.', he: 'כלל ב-CloudWatch שעוקב אחרי metric ומודיע לך כשהוא חוצה סף.' },
    { term: 'Logs Insights', aka: ['CloudWatch Logs Insights'], en: 'The CloudWatch query tool for logs: filter, group and compute statistics over log events.', he: 'כלי השאילתות של CloudWatch ל-logs: סינון, קיבוץ וחישוב סטטיסטיקות על אירועי log.' },
    { term: 'Throttling', aka: ['throttled', 'throttle', 'throttles'], en: 'When a service rejects your request because you went over a rate limit (quota). HTTP status 429.', he: 'כששירות דוחה את הבקשה שלך כי עברת מגבלת קצב (quota). קוד HTTP 429.' },
    { term: 'Application inference profile', aka: ['AIP', 'application inference profiles'], en: 'A tagged resource you create for one model. You pass its ARN as modelId, and its tags show up in your cost reports.', he: 'משאב מתויג שאתה יוצר עבור מודל אחד. מעבירים את ה-ARN שלו כ-modelId, והתגים שלו מופיעים בדוחות העלות.' },
    { term: 'Request metadata', aka: ['requestMetadata'], en: 'Key-value tags you attach to a single model call. They appear only in model invocation logs.', he: 'תגי מפתח-ערך שמצמידים לקריאה אחת למודל. הם מופיעים רק ב-model invocation logs.' },
    { term: 'PII', aka: ['Personally Identifiable Information'], en: 'Personally Identifiable Information: names, emails, phone numbers, ID numbers and other data that points to a real person.', he: 'מידע מזהה אישי: שמות, אימיילים, מספרי טלפון, מספרי זהות ומידע אחר שמצביע על אדם אמיתי.' },
    { term: 'Retention', aka: ['retention period'], en: 'How long stored data is kept before it is deleted automatically.', he: 'כמה זמן מידע שמור נשאר לפני שהוא נמחק אוטומטית.' },
    { term: 'Sampling', aka: ['sampled'], en: 'Keeping or checking only part of the traffic (for example 10% of traces) to save cost.', he: 'שמירה או בדיקה של חלק מהתעבורה בלבד (למשל 10% מה-traces) כדי לחסוך עלות.' },
    { term: 'Baggage', en: 'OpenTelemetry key-value data that travels with a request across services, used here to carry the session ID.', he: 'מידע מפתח-ערך של OpenTelemetry שנוסע עם הבקשה בין שירותים, ומשמש כאן להעברת ה-session ID.' },
    { term: 'Waterfall', aka: ['waterfall view'], en: 'A picture of a trace: each span is a horizontal bar on a time axis, so you see what ran when and what was slow.', he: 'תמונה של trace: כל span הוא פס אופקי על ציר זמן, כך שרואים מה רץ מתי ומה היה איטי.' }
  ],
  lessons: [
    {
      id: 'm12l1', minutes: 13,
      title: { en: 'Three signals, and why agents need traces', he: 'שלושה אותות, ולמה סוכנים צריכים traces' },
      blocks: [
        { t: 'p', en: 'A normal web service is easy to reason about: the same input runs the same code path. An agent is different. The model decides at run time which tools to call, how many times, and with what arguments. Two identical questions can take two different paths. When a user says "it was slow" or "it gave a wrong answer", reading your code tells you almost nothing. You need to see **what actually happened in that one request**. That ability is called [[Observability]].', he: 'שירות web רגיל קל להבנה: אותו קלט מריץ את אותו מסלול קוד. סוכן הוא משהו אחר. המודל מחליט בזמן ריצה לאילו כלים לקרוא, כמה פעמים, ועם אילו ארגומנטים. שתי שאלות זהות יכולות לעבור שני מסלולים שונים. כשמשתמש אומר "זה היה איטי" או "קיבלתי תשובה לא נכונה", קריאת הקוד כמעט לא עוזרת. צריך לראות **מה באמת קרה בבקשה האחת הזו**. ליכולת הזו קוראים [[Observability]].' },
        { t: 'h', en: 'Why agents are harder to debug than normal code', he: 'למה קשה יותר לדבג סוכנים מקוד רגיל' },
        { t: 'list', en: [
          '**The path is not fixed.** The model chooses the steps. You cannot predict them from the code.',
          '**One request = many calls.** A single user question can mean 6 model calls, 4 tool calls and a memory lookup. Any of them can be the slow or broken one.',
          '**Failures are quiet.** A tool returns an error, the model reads it, apologizes nicely and gives a weak answer. HTTP status is 200. Nothing "failed".',
          '**Cost is hidden.** Each loop step sends the whole growing history again. A request that looks normal can burn 80,000 tokens.',
          '**It is [[Non-deterministic]].** You often cannot reproduce the problem by running it again.'
        ], he: [
          '**המסלול לא קבוע.** המודל בוחר את השלבים. אי אפשר לחזות אותם מהקוד.',
          '**בקשה אחת = הרבה קריאות.** שאלה אחת של משתמש יכולה להיות 6 קריאות למודל, 4 קריאות לכלים ושליפה מהזיכרון. כל אחת מהן יכולה להיות האיטית או השבורה.',
          '**כישלונות שקטים.** כלי מחזיר שגיאה, המודל קורא אותה, מתנצל יפה ונותן תשובה חלשה. קוד ה-HTTP הוא 200. שום דבר לא "נכשל".',
          '**העלות מוסתרת.** כל צעד בלולאה שולח שוב את כל ההיסטוריה שהולכת וגדלה. בקשה שנראית רגילה יכולה לשרוף 80,000 טוקנים.',
          '**זה [[Non-deterministic]].** הרבה פעמים אי אפשר לשחזר את הבעיה בהרצה חוזרת.'
        ] },
        { t: 'h', en: 'The three signals', he: 'שלושת האותות' },
        { t: 'p', en: 'All the data a system sends out about itself is called [[Telemetry]]. It comes in three kinds. People call them "the three signals" or "the three pillars".', he: 'כל המידע שמערכת שולחת על עצמה נקרא [[Telemetry]]. הוא מגיע בשלושה סוגים. קוראים להם "שלושת האותות" או "שלושת העמודים".' },
        { t: 'table', head: { en: ['Signal', 'What it is', 'Question it answers', 'Weak point'], he: ['אות', 'מה זה', 'על איזו שאלה הוא עונה', 'נקודת חולשה'] }, rows: {
          en: [
            ['[[Metric]]', 'A number over time: requests per minute, p95 latency, tokens used.', '"Is something wrong? Since when? How bad?"', 'Tells you **that** there is a problem, not **why**.'],
            ['[[Log]]', 'A text record of one event with a timestamp.', '"What exactly happened at this moment?"', 'Thousands of lines from many requests mixed together.'],
            ['[[Trace]]', 'The full path of **one** request, step by step, with timings.', '"Where did this request spend its time, and which step broke?"', 'More data to store, so teams often keep only a sample.']
          ],
          he: [
            ['[[Metric]]', 'מספר לאורך זמן: בקשות לדקה, latency ב-p95, טוקנים שנוצלו.', '"האם משהו לא בסדר? ממתי? כמה חמור?"', 'אומר **ש**יש בעיה, לא **למה**.'],
            ['[[Log]]', 'רשומת טקסט של אירוע אחד עם חותמת זמן.', '"מה בדיוק קרה ברגע הזה?"', 'אלפי שורות מהרבה בקשות מעורבבות יחד.'],
            ['[[Trace]]', 'המסלול המלא של בקשה **אחת**, שלב אחרי שלב, עם זמנים.', '"איפה הבקשה הזו בילתה את הזמן, ואיזה שלב נשבר?"', 'יותר מידע לשמור, ולכן צוותים שומרים לעיתים רק מדגם.']
          ] } },
        { t: 'note', kind: 'tip', en: 'The pro workflow is always the same: a **metric** (or an alarm on it) tells you something is wrong → you find an example **trace** → inside the slow or failed span you read the **logs**. Metric → trace → log. From wide to narrow.', he: 'תהליך העבודה של מקצוען תמיד זהה: **metric** (או alarm עליו) אומר שמשהו לא בסדר ← מוצאים **trace** לדוגמה ← בתוך ה-span האיטי או הכושל קוראים את ה-**logs**. Metric ← trace ← log. מהרחב לצר.' },
        { t: 'quiz', q: { en: 'At 14:05 your support agent starts answering slowly. Which signal tells you first that the problem started at 14:05 and affects 30% of requests?', he: 'ב-14:05 סוכן התמיכה שלך מתחיל לענות לאט. איזה אות יגיד לך ראשון שהבעיה התחילה ב-14:05 ומשפיעה על 30% מהבקשות?' },
          options: { en: ['A metric', 'A single trace', 'The application log of one request', 'The source code'], he: ['Metric', 'Trace בודד', 'ה-log של בקשה אחת', 'קוד המקור'] },
          answer: 0, explain: { en: 'Metrics are numbers over time for all traffic, so they show when a problem started and how wide it is. A trace is one request: it shows why that request was slow, but not how many others are.', he: 'Metrics הם מספרים לאורך זמן על כל התעבורה, ולכן הם מראים מתי בעיה התחילה וכמה היא רחבה. Trace הוא בקשה אחת: הוא מראה למה היא הייתה איטית, אבל לא כמה אחרות כאלה.' } },
        { t: 'h', en: 'Session, trace, span', he: 'Session, trace, span' },
        { t: 'p', en: 'Agent telemetry is organized in three levels. Learn these words well. Every dashboard you will open uses them.', he: 'הטלמטריה של סוכן מאורגנת בשלוש רמות. כדאי להכיר את המילים האלה טוב. כל דשבורד שתפתח משתמש בהן.' },
        { t: 'list', en: [
          '[[Session]] — one whole conversation of one user with the agent. It can last minutes or hours.',
          '[[Trace]] — one request inside the session: one user turn and everything the agent did to answer it.',
          '[[Span]] — one step inside the trace: a model call, a tool call, a retrieval, a memory read. Spans are nested: the "agent turn" span is the parent of the "model call" spans inside it.'
        ], he: [
          '[[Session]] — שיחה שלמה אחת של משתמש אחד עם הסוכן. יכולה להימשך דקות או שעות.',
          '[[Trace]] — בקשה אחת בתוך ה-session: תור אחד של המשתמש וכל מה שהסוכן עשה כדי לענות עליו.',
          '[[Span]] — שלב אחד בתוך ה-trace: קריאה למודל, קריאה לכלי, אחזור, קריאה מהזיכרון. Spans מקוננים: ה-span של "תור הסוכן" הוא האב של spans "קריאה למודל" שבתוכו.'
        ] },
        { t: 'code', lang: 'text', code: 'session  7f3a...   (user: dana, 4 turns)\n└─ trace  turn 3: "Where is my order 1182?"            total 6.4 s\n   ├─ span  agent.invoke                                6.4 s\n   │  ├─ span  chat  claude-sonnet   in 2,100 / out 60    1.1 s   → wants tool get_order\n   │  ├─ span  execute_tool  get_order                   3.9 s   ← slow!\n   │  └─ span  chat  claude-sonnet   in 2,450 / out 180   1.4 s   → final answer\n', caption: { en: 'One trace drawn as a tree. Drawn on a time axis, the same thing is called a waterfall. Names and numbers are an illustration.', he: 'Trace אחד שמצויר כעץ. כשמציירים אותו על ציר זמן, קוראים לאותו דבר waterfall. השמות והמספרים הם להמחשה.' } },
        { t: 'p', en: 'Look at the tree. In ten seconds you know three things that the code could never tell you: the model was called twice, the tool took 3.9 of the 6.4 seconds, and the second model call got 350 more input tokens than the first (the tool result). This picture, drawn with bars on a time axis, is a [[Waterfall]].', he: 'תסתכל על העץ. תוך עשר שניות אתה יודע שלושה דברים שהקוד לעולם לא היה מספר לך: המודל נקרא פעמיים, הכלי לקח 3.9 מתוך 6.4 השניות, והקריאה השנייה למודל קיבלה 350 טוקני קלט יותר מהראשונה (תוצאת הכלי). לתמונה הזו, כשהיא מצוירת עם פסים על ציר זמן, קוראים [[Waterfall]].' },
        { t: 'sim', id: 'trace', title: { en: 'Read a trace waterfall', he: 'קרא waterfall של trace' }, intro: { en: 'Open the spans one by one. Find the step that eats the time, the step that failed quietly, and the place where the token count jumps.', he: 'פתח את ה-spans אחד אחד. מצא את השלב שאוכל את הזמן, את השלב שנכשל בשקט, ואת המקום שבו מספר הטוקנים קופץ.' } },
        { t: 'h', en: 'OpenTelemetry: one standard for everybody', he: 'OpenTelemetry: תקן אחד לכולם' },
        { t: 'p', en: '[[OpenTelemetry]] (short: **OTel**) is an open standard for telemetry. It defines what a span looks like, how spans are linked into a trace, and how to send them over the network. Because it is a standard, your agent code does not care which monitoring product reads the data. AgentCore Observability stores and shows data in the OpenTelemetry format.', he: '[[OpenTelemetry]] (בקיצור: **OTel**) הוא תקן פתוח לטלמטריה. הוא מגדיר איך נראה span, איך spans מקושרים ל-trace, ואיך שולחים אותם ברשת. מכיוון שזה תקן, לקוד הסוכן לא אכפת איזה מוצר ניטור קורא את המידע. AgentCore Observability שומר ומציג מידע בפורמט של OpenTelemetry.' },
        { t: 'list', en: [
          '[[Instrumentation]] — the code that creates spans. **Auto-instrumentation** wraps known libraries (the model SDK, the agent framework, HTTP clients) so spans appear without you writing them.',
          '[[ADOT]] — AWS Distro for OpenTelemetry. The OpenTelemetry build that AWS supports. For Python it is the package `aws-opentelemetry-distro`, and you start your program through the wrapper command `opentelemetry-instrument`.',
          '[[Attribute]] — a key-value pair on a span. This is where the useful details live: which model, how many tokens, which tool.'
        ], he: [
          '[[Instrumentation]] — הקוד שיוצר spans. **Auto-instrumentation** עוטף ספריות מוכרות (ה-SDK של המודל, ה-framework של הסוכן, לקוחות HTTP) כך ש-spans מופיעים בלי שתכתוב אותם.',
          '[[ADOT]] — AWS Distro for OpenTelemetry. הגרסה של OpenTelemetry ש-AWS תומכת בה. ב-Python זו החבילה `aws-opentelemetry-distro`, ומפעילים את התוכנית דרך פקודת העטיפה `opentelemetry-instrument`.',
          '[[Attribute]] — זוג מפתח-ערך על span. כאן נמצאים הפרטים השימושיים: איזה מודל, כמה טוקנים, איזה כלי.'
        ] },
        { t: 'h3', en: 'GenAI semantic conventions', he: 'GenAI semantic conventions' },
        { t: 'p', en: 'If every framework invented its own attribute names, no dashboard could work with all of them. So the OpenTelemetry community agreed on names for AI workloads: the [[GenAI semantic conventions]]. They all start with `gen_ai.`. Frameworks such as Strands, LangChain and CrewAI emit them, and the CloudWatch dashboards and AgentCore Evaluations read them.', he: 'אם כל framework היה ממציא שמות attributes משלו, שום דשבורד לא היה עובד עם כולם. לכן קהילת OpenTelemetry הסכימה על שמות לעומסי AI: ה-[[GenAI semantic conventions]]. כולם מתחילים ב-`gen_ai.`. Frameworks כמו Strands, LangChain ו-CrewAI פולטים אותם, והדשבורדים של CloudWatch ו-AgentCore Evaluations קוראים אותם.' },
        { t: 'table', head: { en: ['Attribute', 'Meaning'], he: ['Attribute', 'משמעות'] }, rows: {
          en: [['`gen_ai.operation.name`', 'What kind of step this is, for example a chat call or a tool execution.'], ['`gen_ai.request.model`', 'The model that was asked.'], ['`gen_ai.usage.input_tokens`', 'Input tokens of this model call.'], ['`gen_ai.usage.output_tokens`', 'Output tokens of this model call.'], ['`gen_ai.tool.name`', 'The tool that was executed.'], ['`gen_ai.evaluation.score.value`', 'A score written by an evaluator and linked to the trace.']],
          he: [['`gen_ai.operation.name`', 'איזה סוג שלב זה, למשל קריאת chat או הרצת כלי.'], ['`gen_ai.request.model`', 'המודל שנשאל.'], ['`gen_ai.usage.input_tokens`', 'טוקני הקלט של הקריאה הזו למודל.'], ['`gen_ai.usage.output_tokens`', 'טוקני הפלט של הקריאה הזו למודל.'], ['`gen_ai.tool.name`', 'הכלי שהורץ.'], ['`gen_ai.evaluation.score.value`', 'ציון שכתב evaluator ומקושר ל-trace.']] } },
        { t: 'note', kind: 'warn', en: 'The GenAI conventions are still growing. The exact set of names depends on the version of your framework or instrumentation library. The idea is stable: `gen_ai.*` attributes on spans. Check the spans your own agent emits before you build queries on a name.', he: 'ה-GenAI conventions עדיין מתפתחים. רשימת השמות המדויקת תלויה בגרסה של ה-framework או של ספריית ה-instrumentation שלך. הרעיון יציב: attributes מסוג `gen_ai.*` על spans. בדוק את ה-spans שהסוכן שלך פולט לפני שאתה בונה שאילתות על שם מסוים.' },
        { t: 'match', prompt: { en: 'Match each word to what it is.', he: 'התאם כל מילה למה שהיא.' }, pairs: [
          { a: 'Session', b: { en: 'A whole conversation, made of many requests', he: 'שיחה שלמה, שמורכבת מהרבה בקשות' } },
          { a: 'Trace', b: { en: 'One request from start to end', he: 'בקשה אחת מההתחלה עד הסוף' } },
          { a: 'Span', b: { en: 'One timed step, such as a single tool call', he: 'שלב מתוזמן אחד, כמו קריאה אחת לכלי' } },
          { a: 'Attribute', b: { en: 'A key-value detail on a step, such as the token count', he: 'פרט מפתח-ערך על שלב, כמו מספר הטוקנים' } },
          { a: 'Instrumentation', b: { en: 'The code that produces the steps and details', he: 'הקוד שמייצר את השלבים והפרטים' } }
        ] },
        { t: 'quiz', q: { en: 'A user asked one question. Your agent called the model 3 times and a tool 2 times. In OpenTelemetry terms, what did this create?', he: 'משתמש שאל שאלה אחת. הסוכן שלך קרא למודל 3 פעמים ולכלי פעמיים. במונחי OpenTelemetry, מה נוצר?' },
          options: { en: ['5 traces in 5 sessions', '1 trace with several spans', '5 sessions with 1 span each', '1 span with 5 traces'], he: ['5 traces ב-5 sessions', 'trace אחד עם כמה spans', '5 sessions עם span אחד בכל אחד', 'span אחד עם 5 traces'] },
          answer: 1, explain: { en: 'One user turn = one trace. Each model call and tool call is a span inside it (plus a parent span for the turn). The session is the whole conversation and holds all the traces.', he: 'תור אחד של משתמש = trace אחד. כל קריאה למודל וכל קריאה לכלי היא span בתוכו (ועוד span אב לתור). ה-session הוא כל השיחה ומחזיק את כל ה-traces.' } },
          { t: 'quiz', q: { en: 'Your team wants a dashboard of token usage per model across three agents: one in Strands, one in LangChain, one in CrewAI. Why can one dashboard serve all three?', he: 'הצוות רוצה דשבורד של צריכת טוקנים לפי מודל על פני שלושה סוכנים: אחד ב-Strands, אחד ב-LangChain, אחד ב-CrewAI. למה דשבורד אחד יכול לשרת את שלושתם?' },
          options: { en: ['Because all three run the same model', 'Because CloudWatch translates each framework separately by hand', 'Because all three emit spans with the same GenAI semantic convention attribute names', 'Because token usage is stored in CloudTrail'], he: ['כי שלושתם מריצים את אותו מודל', 'כי CloudWatch מתרגם כל framework בנפרד באופן ידני', 'כי שלושתם פולטים spans עם אותם שמות attributes לפי GenAI semantic conventions', 'כי צריכת הטוקנים נשמרת ב-CloudTrail'] },
          answer: 2, explain: { en: 'A shared naming standard is the whole point of semantic conventions: `gen_ai.usage.input_tokens` means the same thing from any framework. CloudTrail is an audit log of API calls, not a place for span attributes.', he: 'תקן שמות משותף הוא כל הרעיון של semantic conventions: `gen_ai.usage.input_tokens` אומר אותו דבר מכל framework. CloudTrail הוא יומן ביקורת של קריאות API, לא מקום ל-attributes של spans.' } },
        { t: 'reveal', q: { en: 'Interview question: "Our agent returns HTTP 200 for every request, so why do we need tracing?"', he: 'שאלת ראיון: "הסוכן שלנו מחזיר HTTP 200 לכל בקשה, אז למה צריך tracing?"' },
          a: { en: 'Because for an agent, 200 only means "some text came back". It says nothing about quality, cost or the path. A tool can fail inside the loop and the model will still write a polite answer. A trace shows each model call and tool call with its input, output, duration and tokens. That is how you find silent tool errors, loops, slow steps and token explosions. Metrics tell me that something changed, traces tell me why.', he: 'כי בסוכן, 200 אומר רק "חזר טקסט כלשהו". זה לא אומר כלום על איכות, עלות או המסלול. כלי יכול להיכשל בתוך הלולאה והמודל עדיין יכתוב תשובה מנומסת. Trace מראה כל קריאה למודל וכל קריאה לכלי עם הקלט, הפלט, המשך והטוקנים. כך מוצאים שגיאות כלים שקטות, לולאות, שלבים איטיים והתפוצצות טוקנים. Metrics אומרים לי שמשהו השתנה, traces אומרים לי למה.' } }
      ]
    },
    {
      id: 'm12l2', minutes: 15,
      title: { en: 'AgentCore Observability: turn it on and read it', he: 'AgentCore Observability: להפעיל ולקרוא' },
      blocks: [
        { t: 'p', en: 'AgentCore Observability is not a separate database. It is a set of conventions and ready-made screens: your agent emits [[Telemetry]] in [[OpenTelemetry]] format, the data lands in [[CloudWatch]], and CloudWatch shows it in dashboards built for agents. You pay normal CloudWatch prices for ingestion, storage and queries. There is no extra AgentCore fee for it.', he: 'AgentCore Observability הוא לא מסד נתונים נפרד. זה אוסף של מוסכמות ומסכים מוכנים: הסוכן שלך פולט [[Telemetry]] בפורמט [[OpenTelemetry]], המידע נוחת ב-[[CloudWatch]], ו-CloudWatch מציג אותו בדשבורדים שנבנו לסוכנים. משלמים מחירי CloudWatch רגילים על קליטה, אחסון ושאילתות. אין על זה תשלום נוסף של AgentCore.' },
        { t: 'h', en: 'What you get, and what you must switch on', he: 'מה מקבלים, ומה צריך להדליק' },
        { t: 'table', head: { en: ['Source', 'What it gives', 'What you must do'], he: ['מקור', 'מה הוא נותן', 'מה צריך לעשות'] }, rows: {
          en: [
            ['Runtime: built-in metrics', 'Invocations, Throttles, errors, Latency, session counts, CPU and memory use. [[Namespace]] `AWS/Bedrock-AgentCore`.', 'Nothing. They are published for every runtime.'],
            ['Runtime: logs', 'A [[Log group]] is created automatically for each agent endpoint.', 'Nothing for the basic logs.'],
            ['Your agent code: spans', 'Model calls, tool calls and framework steps as spans with `gen_ai.*` attributes.', 'Add the [[ADOT]] package and start the agent with `opentelemetry-instrument`. Enable [[Transaction Search]] once per account.'],
            ['Memory, Gateway, built-in tools, Identity', 'Spans and application logs of the managed resource itself.', 'Turn on **Tracing** and add **Log delivery** on each resource.']
          ],
          he: [
            ['Runtime: metrics מובנים', 'Invocations, Throttles, שגיאות, Latency, מספר sessions, שימוש ב-CPU ובזיכרון. [[Namespace]] בשם `AWS/Bedrock-AgentCore`.', 'כלום. הם מתפרסמים לכל runtime.'],
            ['Runtime: logs', '[[Log group]] נוצר אוטומטית לכל endpoint של סוכן.', 'כלום בשביל ה-logs הבסיסיים.'],
            ['קוד הסוכן שלך: spans', 'קריאות למודל, קריאות לכלים ושלבי framework כ-spans עם attributes מסוג `gen_ai.*`.', 'להוסיף את חבילת [[ADOT]] ולהפעיל את הסוכן עם `opentelemetry-instrument`. להפעיל [[Transaction Search]] פעם אחת לחשבון.'],
            ['Memory, Gateway, כלים מובנים, Identity', 'Spans ו-application logs של המשאב המנוהל עצמו.', 'להדליק **Tracing** ולהוסיף **Log delivery** על כל משאב.']
          ] } },
        { t: 'h', en: 'Step 1 (once per account): Transaction Search', he: 'שלב 1 (פעם אחת לחשבון): Transaction Search' },
        { t: 'p', en: 'Spans must be stored somewhere searchable. [[Transaction Search]] is the CloudWatch feature that ingests spans as structured logs. Until you enable it, the agent dashboards stay empty even if your agent is perfectly instrumented. This is the most common "why do I see nothing?" mistake.', he: 'Spans צריכים להישמר במקום שאפשר לחפש בו. [[Transaction Search]] היא היכולת של CloudWatch שקולטת spans כ-logs מובנים. עד שמפעילים אותה, הדשבורדים של הסוכנים נשארים ריקים גם אם הסוכן שלך עם instrumentation מושלם. זו הטעות הכי נפוצה של "למה אני לא רואה כלום?".' },
        { t: 'console', service: 'CloudWatch', nav: ['#Application Signals (APM)', 'Transaction search', '#GenAI Observability', 'Bedrock AgentCore'], active: 'Transaction search',
          crumbs: ['CloudWatch', 'Application Signals (APM)', 'Transaction search'],
          heading: 'Transaction search',
          panels: [ { title: 'Enable Transaction Search', n: 1, fields: [
            { label: 'Ingest spans as structured logs', type: 'toggle', value: true, n: 2 }
          ] } ],
          buttons: ['Cancel', 'Save'],
          callouts: [
            { n: 1, en: 'One switch for the whole account. Do it once before your first agent goes live.', he: 'מתג אחד לכל החשבון. עושים את זה פעם אחת לפני שהסוכן הראשון עולה.' },
            { n: 2, en: 'This is the important tick: spans are written to CloudWatch Logs, so they can be searched and shown in the GenAI dashboards.', he: 'זה הסימון החשוב: ה-spans נכתבים ל-CloudWatch Logs, כך שאפשר לחפש בהם ולהציג אותם בדשבורדים של GenAI.' }
          ],
          caption: { en: 'Simplified. Path: CloudWatch → Application Signals (APM) → Transaction search → Enable Transaction Search → tick the option to ingest spans as structured logs → Save.', he: 'מפושט. הנתיב: CloudWatch ← Application Signals (APM) ← Transaction search ← Enable Transaction Search ← מסמנים את האפשרות לקלוט spans כ-logs מובנים ← Save.' } },
        { t: 'p', en: 'The same thing from the AWS CLI is three commands: a resource policy that lets X-Ray write to the span log groups, a command that sends trace segments to CloudWatch Logs, and a command that sets how many spans are indexed.', he: 'אותו דבר מה-AWS CLI הוא שלוש פקודות: resource policy שמאפשרת ל-X-Ray לכתוב ל-log groups של spans, פקודה ששולחת trace segments ל-CloudWatch Logs, ופקודה שקובעת כמה spans עוברים אינדוקס.' },
        { t: 'code', lang: 'bash', code: 'aws logs put-resource-policy --policy-name MyResourcePolicy \\\n  --policy-document \'{... allow xray.amazonaws.com logs:PutLogEvents on aws/spans and /aws/application-signals/data ...}\'\n\naws xray update-trace-segment-destination --destination CloudWatchLogs\n\naws xray update-indexing-rule --name "Default" \\\n  --rule \'{"Probabilistic": {"DesiredSamplingPercentage": 100}}\'', caption: { en: 'The policy document is shortened here. Take the full JSON from the AgentCore docs.', he: 'מסמך ה-policy מקוצר כאן. את ה-JSON המלא לוקחים מהתיעוד של AgentCore.' } },
        { t: 'h', en: 'Step 2: instrument the agent on Runtime', he: 'שלב 2: instrumentation לסוכן ב-Runtime' },
        { t: 'p', en: 'For an agent hosted on AgentCore Runtime you need two small things: the ADOT package in your dependencies, and the wrapper command in front of your start command. Runtime sets the needed ADOT environment variables for you. Projects created by the AgentCore CLI already include the package.', he: 'לסוכן שמתארח ב-AgentCore Runtime צריך שני דברים קטנים: חבילת ADOT ב-dependencies, ופקודת העטיפה לפני פקודת ההפעלה. Runtime מגדיר בשבילך את משתני הסביבה של ADOT. פרויקטים שנוצרו ב-AgentCore CLI כבר כוללים את החבילה.' },
        { t: 'code', lang: 'text', code: '# requirements.txt\naws-opentelemetry-distro>=0.18.0\nboto3\n\n# Dockerfile\nCMD ["opentelemetry-instrument", "python", "main.py"]' },
        { t: 'fill', prompt: { en: 'Your container starts the agent with `python main.py`, and no spans appear. Fix the start command so ADOT auto-instruments the agent.', he: 'הקונטיינר שלך מפעיל את הסוכן עם `python main.py`, ולא מופיעים spans. תקן את פקודת ההפעלה כך ש-ADOT יעשה auto-instrumentation לסוכן.' },
          lang: 'text', code: '# requirements.txt\n{{1}}>=0.18.0\n\n# Dockerfile\nCMD ["{{2}}", "python", "main.py"]',
          blanks: [ { accept: ['aws-opentelemetry-distro'], hint: { en: 'the ADOT Python package', he: 'חבילת ה-Python של ADOT' } }, { accept: ['opentelemetry-instrument'], hint: { en: 'the wrapper command', he: 'פקודת העטיפה' } } ],
          explain: { en: 'The package brings the instrumentation, and the wrapper activates it before your code starts. Without the wrapper the package is installed but does nothing.', he: 'החבילה מביאה את ה-instrumentation, והעטיפה מפעילה אותו לפני שהקוד שלך מתחיל. בלי העטיפה החבילה מותקנת אבל לא עושה כלום.' } },
        { t: 'h', en: 'Step 3: the other AgentCore resources', he: 'שלב 3: שאר המשאבים של AgentCore' },
        { t: 'p', en: 'Memory, Gateway, the built-in tools and Identity are managed services. Their inner steps are invisible to your agent code, so you switch on their telemetry on the resource itself. On each resource page in the AgentCore console you enable **Tracing**, and you add a **Log delivery** with log type `APPLICATION_LOGS`. The destination can be CloudWatch Logs, S3 or Firehose.', he: 'Memory, Gateway, הכלים המובנים ו-Identity הם שירותים מנוהלים. השלבים הפנימיים שלהם לא נראים לקוד הסוכן, ולכן מדליקים את הטלמטריה שלהם על המשאב עצמו. בכל עמוד משאב בקונסול של AgentCore מפעילים **Tracing**, ומוסיפים **Log delivery** עם log type בשם `APPLICATION_LOGS`. היעד יכול להיות CloudWatch Logs, S3 או Firehose.' },
        { t: 'console', service: 'Amazon Bedrock AgentCore', nav: ['#Resources', 'Gateways', 'Evaluations'], active: 'Gateways',
          crumbs: ['Amazon Bedrock AgentCore', 'Gateways', 'support-gateway'],
          heading: 'support-gateway', actions: ['Edit'],
          panels: [
            { title: 'Tracing', n: 1, fields: [ { label: 'Tracing', type: 'text', value: 'Enabled' } ] },
            { title: 'Log delivery', n: 2, table: { cols: ['Log type', 'Destination', 'Status'], rows: [['APPLICATION_LOGS', 'CloudWatch Logs', 'Active']] } }
          ],
          callouts: [
            { n: 1, en: 'Tracing: Edit → Enable → Save. Now each tool call through the gateway becomes a span you can see inside the agent trace.', he: 'Tracing: Edit ← Enable ← Save. מעכשיו כל קריאה לכלי דרך ה-gateway הופכת ל-span שרואים בתוך ה-trace של הסוכן.' },
            { n: 2, en: 'Log delivery sends the resource logs to a destination you choose: CloudWatch Logs, S3 or Firehose.', he: 'Log delivery שולח את ה-logs של המשאב ליעד שאתה בוחר: CloudWatch Logs, S3 או Firehose.' }
          ],
          caption: { en: 'Simplified view of the observability part of a Gateway page. The same two settings exist on Memory, built-in tool and Identity resources.', he: 'תצוגה מפושטת של חלק ה-observability בעמוד Gateway. אותן שתי הגדרות קיימות במשאבי Memory, כלים מובנים ו-Identity.' } },
        { t: 'h', en: 'Where the data lands', he: 'איפה המידע נוחת' },
        { t: 'table', head: { en: ['Data', 'Location in CloudWatch Logs'], he: ['מידע', 'מיקום ב-CloudWatch Logs'] }, rows: {
          en: [
            ['Runtime logs', '`/aws/bedrock-agentcore/runtimes/<agent_id>-<endpoint_name>` (created automatically). OTEL logs go to the stream `otel-rt-logs`.'],
            ['Spans, new agents', 'The `spans` [[Log stream]] inside the agent\'s **own** log group.'],
            ['Spans, older agents', 'The shared log group `aws/spans`.'],
            ['Memory / Gateway logs', '`/aws/vendedlogs/bedrock-agentcore/{memory|gateway}/APPLICATION_LOGS/{resource-id}`'],
            ['Evaluation results', '`/aws/bedrock-agentcore/evaluations/results/<online-evaluation-config-id>`']
          ],
          he: [
            ['Logs של Runtime', '`/aws/bedrock-agentcore/runtimes/<agent_id>-<endpoint_name>` (נוצר אוטומטית). Logs של OTEL הולכים ל-stream בשם `otel-rt-logs`.'],
            ['Spans, סוכנים חדשים', 'ה-[[Log stream]] בשם `spans` בתוך ה-log group **של הסוכן עצמו**.'],
            ['Spans, סוכנים ישנים', 'ה-log group המשותף `aws/spans`.'],
            ['Logs של Memory / Gateway', '`/aws/vendedlogs/bedrock-agentcore/{memory|gateway}/APPLICATION_LOGS/{resource-id}`'],
            ['תוצאות evaluation', '`/aws/bedrock-agentcore/evaluations/results/<online-evaluation-config-id>`']
          ] } },
        { t: 'note', kind: 'warn', en: '**The 2026 change.** Since 2026-07-20 (in supported Regions), new agents write their spans to the `spans` stream in their own log group. This is called the unified span destination. Agents created before that still write to the shared `aws/spans` group. So a query that worked for an old agent can return nothing for a new one, only because it looks in the wrong log group. You can set the behavior per agent with the environment variable `UNIFIED_TRACES_DESTINATION_ENABLED=true|false`.', he: '**השינוי של 2026.** מאז 2026-07-20 (ב-Regions נתמכים), סוכנים חדשים כותבים את ה-spans שלהם ל-stream בשם `spans` בתוך ה-log group של עצמם. קוראים לזה unified span destination. סוכנים שנוצרו לפני כן עדיין כותבים ל-group המשותף `aws/spans`. לכן שאילתה שעבדה לסוכן ישן יכולה להחזיר כלום לסוכן חדש, רק כי היא מחפשת ב-log group הלא נכון. אפשר לקבוע את ההתנהגות לכל סוכן עם משתנה הסביבה `UNIFIED_TRACES_DESTINATION_ENABLED=true|false`.' },
        { t: 'p', en: 'Why did AWS change it? When each agent keeps spans in its own log group, you can give a team access to exactly its own agent, set a different [[Retention]] per agent, and see the cost per agent. One shared group for the whole account made all three hard.', he: 'למה AWS שינתה את זה? כשכל סוכן שומר spans ב-log group משלו, אפשר לתת לצוות גישה בדיוק לסוכן שלו, לקבוע [[Retention]] שונה לכל סוכן, ולראות עלות לכל סוכן. Group משותף אחד לכל החשבון הקשה על שלושת הדברים.' },
        { t: 'quiz', q: { en: 'You deployed a new agent last week. It is instrumented and Transaction Search is on. A teammate runs an old saved query on the `aws/spans` log group and finds no spans from your agent. What is the most likely reason?', he: 'העלית סוכן חדש בשבוע שעבר. יש לו instrumentation ו-Transaction Search דלוק. חבר צוות מריץ שאילתה ישנה ושמורה על ה-log group בשם `aws/spans` ולא מוצא spans של הסוכן שלך. מה הסיבה הכי סבירה?' },
          options: { en: ['Spans are only kept for one hour', 'The agent must be redeployed with `--platform-version V2`', 'CloudTrail data events are off', 'New agents write spans to the `spans` stream in their own log group, not to `aws/spans`'], he: ['Spans נשמרים רק לשעה', 'צריך להעלות את הסוכן מחדש עם `--platform-version V2`', 'ה-data events של CloudTrail כבויים', 'סוכנים חדשים כותבים spans ל-stream בשם `spans` ב-log group של עצמם, לא ל-`aws/spans`'] },
          answer: 3, explain: { en: 'Agents created after 2026-07-20 use the unified span destination: their own log group. The old shared group only holds spans of older agents. CloudTrail has nothing to do with spans.', he: 'סוכנים שנוצרו אחרי 2026-07-20 משתמשים ב-unified span destination: ה-log group של עצמם. ה-group המשותף הישן מחזיק רק spans של סוכנים ישנים. ל-CloudTrail אין קשר ל-spans.' } },
        { t: 'h', en: 'An agent that runs outside Runtime', he: 'סוכן שרץ מחוץ ל-Runtime' },
        { t: 'p', en: 'You can use AgentCore Observability for an agent on EC2, EKS, Lambda or your laptop. Then nobody sets things up for you: you create the log group yourself and set the ADOT environment variables by hand.', he: 'אפשר להשתמש ב-AgentCore Observability גם לסוכן על EC2, EKS, Lambda או הלפטופ שלך. במקרה כזה אף אחד לא מכין לך את הדברים: יוצרים את ה-log group לבד ומגדירים את משתני הסביבה של ADOT ידנית.' },
        { t: 'code', lang: 'bash', code: 'AGENT_OBSERVABILITY_ENABLED=true\nOTEL_PYTHON_DISTRO=aws_distro\nOTEL_PYTHON_CONFIGURATOR=aws_configurator\nOTEL_RESOURCE_ATTRIBUTES=service.name=<agent-name>,aws.log.group.names=/aws/bedrock-agentcore/runtimes/<agent-id>,cloud.resource_id=<AgentEndpointArn:AgentEndpointName>\nOTEL_EXPORTER_OTLP_LOGS_HEADERS=x-aws-log-group=/aws/bedrock-agentcore/runtimes/<agent-id>,x-aws-log-stream=runtime-logs,x-aws-metric-namespace=bedrock-agentcore\nOTEL_EXPORTER_OTLP_PROTOCOL=http/protobuf\nOTEL_TRACES_EXPORTER=otlp', caption: { en: 'Environment variables for an agent outside Runtime. On Lambda you use the AWS Lambda Layer for OpenTelemetry instead.', he: 'משתני סביבה לסוכן מחוץ ל-Runtime. ב-Lambda משתמשים במקום זה ב-AWS Lambda Layer for OpenTelemetry.' } },
        { t: 'p', en: 'One more thing is missing outside Runtime: the session ID. On Runtime the platform knows the session. Outside, you must attach it yourself, or all traces will look like unrelated requests and the Sessions view will be useless. You do it with OpenTelemetry [[Baggage]].', he: 'עוד דבר חסר מחוץ ל-Runtime: ה-session ID. ב-Runtime הפלטפורמה מכירה את ה-session. בחוץ צריך להצמיד אותו לבד, אחרת כל ה-traces ייראו כמו בקשות לא קשורות ותצוגת ה-Sessions תהיה חסרת תועלת. עושים את זה עם [[Baggage]] של OpenTelemetry.' },
        { t: 'fill', prompt: { en: 'Your agent runs on EKS. Attach the session ID to the current request so that CloudWatch can group traces into sessions.', he: 'הסוכן שלך רץ על EKS. הצמד את ה-session ID לבקשה הנוכחית כדי ש-CloudWatch יוכל לקבץ traces ל-sessions.' },
          lang: 'python', code: 'from opentelemetry import baggage\n\nctx = baggage.{{1}}("{{2}}", session_id)',
          blanks: [ { accept: ['set_baggage'], hint: { en: 'set a baggage value', he: 'קביעת ערך baggage' } }, { accept: ['session.id'], hint: { en: 'the key name: two words joined by a dot', he: 'שם המפתח: שתי מילים שמחוברות בנקודה' } } ],
          explain: { en: '`baggage.set_baggage("session.id", session_id)` makes the session ID travel with the request, so every span of this turn is linked to the session.', he: '`baggage.set_baggage("session.id", session_id)` גורם ל-session ID לנסוע עם הבקשה, כך שכל span של התור הזה מקושר ל-session.' } },
        { t: 'note', kind: 'info', en: 'Want to send telemetry to another observability vendor instead of CloudWatch? Set `DISABLE_ADOT_OBSERVABILITY=true` on the runtime and configure your own OpenTelemetry exporter.', he: 'רוצה לשלוח טלמטריה לספק observability אחר במקום CloudWatch? קבע `DISABLE_ADOT_OBSERVABILITY=true` על ה-runtime והגדר exporter משלך של OpenTelemetry.' },
        { t: 'h', en: 'The dashboards: sessions → traces → spans', he: 'הדשבורדים: sessions ← traces ← spans' },
        { t: 'p', en: 'Open the CloudWatch console → **GenAI Observability** → **Bedrock AgentCore**. There are three views: **Agents**, **Sessions** and **Traces**. You drill down exactly along the three levels you learned: pick an agent, pick a session, open one trace, click a span. The AgentCore console also has its own **Observability** page that leads to the same data.', he: 'פותחים את הקונסול של CloudWatch ← **GenAI Observability** ← **Bedrock AgentCore**. יש שלוש תצוגות: **Agents**, **Sessions** ו-**Traces**. יורדים פנימה בדיוק לפי שלוש הרמות שלמדת: בוחרים סוכן, בוחרים session, פותחים trace אחד, לוחצים על span. גם בקונסול של AgentCore יש עמוד **Observability** משלו שמוביל לאותו מידע.' },
        { t: 'console', service: 'CloudWatch', nav: ['#Application Signals (APM)', 'Transaction search', '#GenAI Observability', 'Model Invocations', 'Bedrock AgentCore'], active: 'Bedrock AgentCore',
          crumbs: ['CloudWatch', 'GenAI Observability', 'Bedrock AgentCore'],
          heading: 'Bedrock AgentCore',
          panels: [
            { title: 'Agents', n: 1, table: { cols: ['Agent', 'Endpoint', 'Sessions', 'Traces', 'Errors'], rows: [['@support_agent', 'DEFAULT', '1,204', '5,310', '42'], ['@billing_agent', 'prod', '388', '1,102', '3']] } },
            { title: 'Sessions', n: 2, table: { cols: ['Session ID', 'Traces', 'Duration'], rows: [['@7f3a9c1e-...', '4', '6 min'], ['@b21d77a0-...', '11', '31 min']] } },
            { title: 'Traces', n: 3, table: { cols: ['Trace ID', 'Spans', 'Duration', 'Status'], rows: [['@1-67a1...', '9', '6.4 s', 'OK'], ['@1-67a2...', '31', '48.2 s', 'Error']] } }
          ],
          callouts: [
            { n: 1, en: 'Agents view: one row per agent endpoint. Each agent endpoint also has an Evaluations tab with quality scores.', he: 'תצוגת Agents: שורה לכל endpoint של סוכן. לכל endpoint של סוכן יש גם לשונית Evaluations עם ציוני איכות.' },
            { n: 2, en: 'Sessions view: whole conversations. A session with many traces and a long duration is worth opening.', he: 'תצוגת Sessions: שיחות שלמות. Session עם הרבה traces ומשך ארוך שווה פתיחה.' },
            { n: 3, en: 'Traces view: single requests. 31 spans and 48 seconds for one turn is a hint of a loop. Click it to see the span waterfall.', he: 'תצוגת Traces: בקשות בודדות. 31 spans ו-48 שניות לתור אחד זה רמז ללולאה. לוחצים כדי לראות את ה-waterfall של ה-spans.' }
          ],
          caption: { en: 'Simplified. The three views (Agents, Sessions, Traces) are real; the columns and numbers are an illustration.', he: 'מפושט. שלוש התצוגות (Agents, Sessions, Traces) אמיתיות; העמודות והמספרים הם להמחשה.' } },
        { t: 'h', en: 'Built-in Runtime metrics', he: 'Metrics מובנים של Runtime' },
        { t: 'table', head: { en: ['Metric', 'Meaning'], he: ['Metric', 'משמעות'] }, rows: {
          en: [['`Invocations`', 'Requests to the data plane API.'], ['`Throttles`', 'Requests rejected with 429.'], ['`System Errors` / `User Errors` / `Total Errors`', '5xx / 4xx / both.'], ['`Latency`', 'From request received to the final response token.'], ['`OverheadLatency`', 'Platform time to first byte, **without** your agent\'s own time (V2).'], ['`Session Count` / `ActiveSessionCount`', 'New sessions created / sessions running now.'], ['`CPUUsed-vCPUHours`, `MemoryUsed-GBHours`', 'Resource use, a billing estimate. May lag up to 60 minutes.']],
          he: [['`Invocations`', 'בקשות ל-API של ה-data plane.'], ['`Throttles`', 'בקשות שנדחו עם 429.'], ['`System Errors` / `User Errors` / `Total Errors`', '5xx / 4xx / שניהם.'], ['`Latency`', 'מקבלת הבקשה עד טוקן התשובה האחרון.'], ['`OverheadLatency`', 'זמן הפלטפורמה עד הבייט הראשון, **בלי** הזמן של הסוכן עצמו (V2).'], ['`Session Count` / `ActiveSessionCount`', 'Sessions חדשים שנוצרו / sessions שרצים עכשיו.'], ['`CPUUsed-vCPUHours`, `MemoryUsed-GBHours`', 'שימוש במשאבים, הערכה לחיוב. יכול להתעכב עד 60 דקות.']] } },
        { t: 'note', kind: 'tip', en: '`Latency` high but `OverheadLatency` low? The platform is fine and the time is inside your agent: the model, a tool or your code. Open a trace. Both high? Look at the platform side: cold starts, image size, quotas.', he: '`Latency` גבוה אבל `OverheadLatency` נמוך? הפלטפורמה בסדר והזמן נמצא בתוך הסוכן שלך: המודל, כלי או הקוד. פותחים trace. שניהם גבוהים? מסתכלים על צד הפלטפורמה: cold starts, גודל ה-image, quotas.' },
        { t: 'note', kind: 'warn', en: 'Runtime has two log types. `APPLICATION_LOGS` include the **request payload** (what the user sent) but not the response. `USAGE_LOGS` are per-session resource usage at 1-second granularity. The first one contains user data, so treat that log group as sensitive.', he: 'ל-Runtime יש שני סוגי logs. `APPLICATION_LOGS` כוללים את ה-**request payload** (מה שהמשתמש שלח) אבל לא את התשובה. `USAGE_LOGS` הם שימוש במשאבים לכל session ברזולוציה של שנייה. הראשון מכיל מידע של משתמשים, ולכן מתייחסים ל-log group הזה כרגיש.' },
        { t: 'terminal', title: { en: 'Lab: from an empty dashboard to a trace', he: 'מעבדה: מדשבורד ריק ל-trace' }, intro: { en: 'Your agent is deployed with the AgentCore CLI, but the dashboards are empty. Enable span storage for the account, send a request, then read logs and traces from the terminal.', he: 'הסוכן שלך הועלה עם AgentCore CLI, אבל הדשבורדים ריקים. הפעל שמירת spans לחשבון, שלח בקשה, ואז קרא logs ו-traces מהטרמינל.' }, shell: 'bash — ~/MyProject',
          steps: [
            { ask: { en: 'Send trace segments to CloudWatch Logs (the X-Ray command with the destination CloudWatchLogs).', he: 'שלח trace segments ל-CloudWatch Logs (פקודת X-Ray עם היעד CloudWatchLogs).' }, accept: ['^aws\\s+xray\\s+update-trace-segment-destination\\s+--destination[= ]\\s*CloudWatchLogs$'], hint: 'aws xray update-trace-segment-destination --destination CloudWatchLogs', output: '{\n    "Destination": "CloudWatchLogs",\n    "Status": "PENDING"\n}' },
            { ask: { en: 'Check that the agent is deployed and see its state.', he: 'בדוק שהסוכן מועלה וראה את המצב שלו.' }, accept: ['^agentcore\\s+status\\b'], hint: 'agentcore status', output: 'runtime  agent   READY' },
            { ask: { en: 'Send the runtime named agent a test request with the prompt "Where is order 1182?".', he: 'שלח ל-runtime בשם agent בקשת בדיקה עם הפרומפט "Where is order 1182?".' }, accept: ['^agentcore\\s+invoke\\s+.*--runtime[= ]\\s*agent\\b.*--payload\\b', '^agentcore\\s+invoke\\s+.*--payload\\b.*--runtime[= ]\\s*agent\\b'], hint: 'agentcore invoke --runtime agent --payload \'{"prompt":"Where is order 1182?"}\'', output: 'Order 1182 was shipped on Monday and should arrive tomorrow.' },
            { ask: { en: 'Show only error-level runtime logs from the last 30 minutes.', he: 'הצג רק logs של runtime ברמת error מ-30 הדקות האחרונות.' }, accept: ['^agentcore\\s+logs\\s+runtime\\b(?=.*--since[= ]\\s*30m)(?=.*--level[= ]\\s*error)'], hint: 'agentcore logs runtime --since 30m --level error', output: '[ERROR] tool get_order: upstream timeout after 3000 ms (retry 1/2)' },
            { ask: { en: 'List the runtime traces from the last 30 minutes.', he: 'הצג רשימה של ה-traces של ה-runtime מ-30 הדקות האחרונות.' }, accept: ['^agentcore\\s+traces\\s+runtime\\s+list\\b.*--since[= ]\\s*30m'], hint: 'agentcore traces runtime list --since 30m', output: 'TRACE ID        SPANS   DURATION   STATUS\n1-67a1...       9       6.4 s      OK' }
          ],
          done: { en: 'You have the full loop: enable span storage, invoke, read logs, list traces. `agentcore traces runtime get` opens one trace; run it with `--help` to see its exact arguments.', he: 'יש לך את כל המעגל: הפעלת שמירת spans, invoke, קריאת logs, רשימת traces. `agentcore traces runtime get` פותח trace אחד; הרץ אותו עם `--help` כדי לראות את הארגומנטים המדויקים.' } },
        { t: 'quiz', q: { en: 'Your agent calls three tools through an AgentCore Gateway. In the trace you see the agent\'s model calls, but nothing about what happened inside the gateway. What is missing?', he: 'הסוכן שלך קורא לשלושה כלים דרך AgentCore Gateway. ב-trace רואים את הקריאות של הסוכן למודל, אבל כלום על מה שקרה בתוך ה-gateway. מה חסר?' },
          options: { en: ['Tracing is not enabled on the Gateway resource', 'The gateway must use the CUSTOM_JWT authorizer', 'Model invocation logging is off', 'The agent needs a bigger context window'], he: ['Tracing לא מופעל על משאב ה-Gateway', 'ה-gateway חייב להשתמש ב-authorizer מסוג CUSTOM_JWT', 'Model invocation logging כבוי', 'הסוכן צריך context window גדול יותר'] },
          answer: 0, explain: { en: 'Managed resources emit their own spans only after you enable Tracing on them (and add Log delivery for logs). Model invocation logging is a Bedrock model feature and does not cover the gateway.', he: 'משאבים מנוהלים פולטים spans משלהם רק אחרי שמפעילים עליהם Tracing (ומוסיפים Log delivery בשביל logs). Model invocation logging הוא יכולת של מודלי Bedrock ולא מכסה את ה-gateway.' } },
        { t: 'order', prompt: { en: 'Put the steps in order: from a new AWS account to a visible trace of an agent on Runtime.', he: 'סדר את השלבים: מחשבון AWS חדש ל-trace גלוי של סוכן ב-Runtime.' }, items: { en: ['Enable CloudWatch Transaction Search for the account', 'Add aws-opentelemetry-distro to the agent dependencies', 'Start the agent with opentelemetry-instrument and deploy', 'Invoke the agent', 'Open GenAI Observability → Bedrock AgentCore → Traces'], he: ['להפעיל CloudWatch Transaction Search לחשבון', 'להוסיף aws-opentelemetry-distro ל-dependencies של הסוכן', 'להפעיל את הסוכן עם opentelemetry-instrument ולהעלות', 'לקרוא לסוכן (invoke)', 'לפתוח GenAI Observability ← Bedrock AgentCore ← Traces'] },
          explain: { en: 'Storage first, then instrumentation, then traffic, then the dashboard. If you invoke before Transaction Search is on, those early spans are not there to find.', he: 'קודם אחסון, אחר כך instrumentation, אחר כך תעבורה, ואז הדשבורד. אם קוראים לסוכן לפני ש-Transaction Search דלוק, ה-spans המוקדמים האלה לא יהיו שם.' } }
      ]
    },
    {
      id: 'm12l3', minutes: 14,
      title: { en: 'Observability for plain Bedrock calls', he: 'Observability לקריאות Bedrock רגילות' },
      blocks: [
        { t: 'p', en: 'Not everything is an agent. A summarizer, a classifier or a RAG endpoint may just call `Converse` once. And under every agent there are model calls too. Bedrock gives you three separate sources for them. Each answers a different question, and mixing them up is a classic interview trap.', he: 'לא הכול סוכן. מסכם, מסווג או endpoint של RAG יכולים פשוט לקרוא ל-`Converse` פעם אחת. וגם מתחת לכל סוכן יש קריאות למודל. Bedrock נותן לך שלושה מקורות נפרדים עבורן. כל אחד עונה על שאלה אחרת, ובלבול ביניהם הוא מלכודת קלאסית בראיונות.' },
        { t: 'table', head: { en: ['Source', 'Question it answers', 'Contains the prompt text?', 'On by default?'], he: ['מקור', 'על איזו שאלה הוא עונה', 'מכיל את טקסט הפרומפט?', 'דלוק כברירת מחדל?'] }, rows: {
          en: [
            ['CloudWatch metrics (`AWS/Bedrock`)', '"How many calls, how slow, how many tokens, how many throttles?"', 'No. Only numbers.', 'Yes'],
            ['[[Model invocation logging]]', '"What exactly was sent to the model and what came back?"', '**Yes.** Full request and response.', '**No**'],
            ['[[CloudTrail]]', '"Who called which API, when, from where?"', 'No. It records the call, not the content.', 'Yes (management events)']
          ],
          he: [
            ['CloudWatch metrics (`AWS/Bedrock`)', '"כמה קריאות, כמה איטי, כמה טוקנים, כמה throttles?"', 'לא. רק מספרים.', 'כן'],
            ['[[Model invocation logging]]', '"מה בדיוק נשלח למודל ומה חזר?"', '**כן.** בקשה ותשובה מלאות.', '**לא**'],
            ['[[CloudTrail]]', '"מי קרא לאיזה API, מתי, מאיפה?"', 'לא. הוא רושם את הקריאה, לא את התוכן.', 'כן (management events)']
          ] } },
        { t: 'h', en: 'Model invocation logging', he: 'Model invocation logging' },
        { t: 'p', en: '[[Model invocation logging]] is an account-level setting, **per Region**. When it is on, Bedrock saves the full request data, the response data and metadata of model calls. It is **disabled by default**, and once you enable it, logs are collected until you delete the logging configuration.', he: '[[Model invocation logging]] היא הגדרה ברמת החשבון, **לכל Region בנפרד**. כשהיא דלוקה, Bedrock שומר את נתוני הבקשה המלאים, נתוני התשובה וה-metadata של קריאות למודל. היא **כבויה כברירת מחדל**, ומרגע שמפעילים אותה, logs נאספים עד שמוחקים את הגדרת ה-logging.' },
        { t: 'list', en: [
          '**What is logged:** `Converse`, `ConverseStream`, `InvokeModel`, `InvokeModelWithResponseStream`, and the OpenAI-compatible Responses and Chat Completions APIs when they are called on `bedrock-runtime`.',
          '**What is NOT logged:** anything sent to the `bedrock-mantle` endpoint. If part of your traffic goes there, you have a blind spot.',
          '**Destinations:** Amazon CloudWatch Logs, Amazon S3, or both. They must be in the same account and Region.',
          '**Data types:** you choose which modalities to log: Text, Image, Embedding, Video.',
          '**Size rule:** JSON bodies up to 100 KB are stored inline. Images and bodies over 100 KB are written to S3 as separate objects, and the log entry holds a reference. So even with a CloudWatch-only setup you should give an S3 location for large data.'
        ], he: [
          '**מה נרשם:** `Converse`, `ConverseStream`, `InvokeModel`, `InvokeModelWithResponseStream`, וגם ה-APIs התואמים ל-OpenAI (Responses ו-Chat Completions) כשקוראים להם על `bedrock-runtime`.',
          '**מה לא נרשם:** כל מה שנשלח ל-endpoint בשם `bedrock-mantle`. אם חלק מהתעבורה שלך הולך לשם, יש לך נקודה עיוורת.',
          '**יעדים:** Amazon CloudWatch Logs, Amazon S3, או שניהם. הם חייבים להיות באותו חשבון ובאותו Region.',
          '**סוגי מידע:** בוחרים אילו modalities לרשום: Text, Image, Embedding, Video.',
          '**כלל הגודל:** גופי JSON עד 100 KB נשמרים inline. תמונות וגופים מעל 100 KB נכתבים ל-S3 כאובייקטים נפרדים, ורשומת ה-log מחזיקה הפניה. לכן גם בהגדרה של CloudWatch בלבד כדאי לתת מיקום S3 למידע גדול.'
        ] },
        { t: 'code', lang: 'json', code: '{\n  "schemaType": "ModelInvocationLog",\n  "schemaVersion": "1.0",\n  "timestamp": "2026-11-13T09:14:02Z",\n  "accountId": "111122223333",\n  "region": "us-east-1",\n  "requestId": "5a1c...",\n  "operation": "Converse",\n  "modelId": "us.anthropic.claude-sonnet-5-5",\n  "identity": { "arn": "arn:aws:sts::111122223333:assumed-role/support-api/user-481" },\n  "requestMetadata": { "feature": "order-status", "tenant": "acme" },\n  "input":  { "inputContentType": "application/json", "inputBodyJson": { "messages": ["..."] }, "inputTokenCount": 2100 },\n  "output": { "outputContentType": "application/json", "outputBodyJson": { "output": "..." }, "outputTokenCount": 60 }\n}', caption: { en: 'One invocation log record (shortened). The field names are the real schema; the values are an example.', he: 'רשומת invocation log אחת (מקוצרת). שמות השדות הם הסכמה האמיתית; הערכים הם דוגמה.' } },
        { t: 'p', en: 'Notice three useful fields. `identity.arn` tells you **who** made the call. `modelId` is the model ID or the inference profile ID. `requestMetadata` is the only field that the caller fills in freely. You will use it in the next lesson to tag calls by feature and tenant.', he: 'שים לב לשלושה שדות שימושיים. `identity.arn` אומר **מי** ביצע את הקריאה. `modelId` הוא מזהה המודל או מזהה ה-inference profile. `requestMetadata` הוא השדה היחיד שהקורא ממלא באופן חופשי. תשתמש בו בשיעור הבא כדי לתייג קריאות לפי פיצ׳ר ו-tenant.' },
        { t: 'console', service: 'Amazon Bedrock', nav: ['Model catalog', 'Guardrails', 'Knowledge bases', 'API keys', 'Settings'], active: 'Settings',
          crumbs: ['Amazon Bedrock', 'Settings'],
          task: { en: 'Turn on model invocation logging for this Region. Your team needs to search prompts with Logs Insights and does not want regular logs in S3. Log text only: no images, embeddings or video.', he: 'הפעל model invocation logging ל-Region הזה. הצוות שלך צריך לחפש פרומפטים עם Logs Insights ולא רוצה logs רגילים ב-S3. רשום טקסט בלבד: בלי תמונות, embeddings או וידאו.' },
          heading: 'Settings',
          panels: [
            { title: 'Model invocation logging', n: 1, desc: 'Collect full request data, response data and metadata for model invocations in this account and Region.', fields: [
              { label: 'Model invocation logging', type: 'toggle', value: false, expect: true, hint: { en: 'It is off by default. Turn it on.', he: 'כבוי כברירת מחדל. הדלק אותו.' } },
              { label: 'Text', type: 'toggle', value: false, n: 2, expect: true, hint: { en: 'You want prompts and answers, which are text.', he: 'אתה רוצה פרומפטים ותשובות, כלומר טקסט.' } },
              { label: 'Image', type: 'toggle', value: false, expect: false, hint: { en: 'The task says text only.', he: 'המשימה אומרת טקסט בלבד.' } },
              { label: 'Embedding', type: 'toggle', value: true, expect: false, hint: { en: 'Text only: turn embeddings off.', he: 'טקסט בלבד: כבה embeddings.' } },
              { label: 'Video', type: 'toggle', value: false, expect: false, hint: { en: 'The task says text only.', he: 'המשימה אומרת טקסט בלבד.' } }
            ] },
            { title: 'Logging destinations', n: 3, fields: [
              { label: 'Destination', type: 'radio', options: ['Amazon S3 only', 'CloudWatch Logs only', 'Both Amazon S3 and CloudWatch Logs'], value: 'Amazon S3 only', expect: 'CloudWatch Logs only', hint: { en: 'Logs Insights queries CloudWatch Logs, and the team does not want regular logs in S3.', he: 'Logs Insights מריץ שאילתות על CloudWatch Logs, והצוות לא רוצה logs רגילים ב-S3.' } }
            ] }
          ],
          buttons: ['Cancel', 'Save settings'],
          callouts: [
            { n: 1, en: 'This switch is per account and per Region. If you use three Regions, you set it three times.', he: 'המתג הזה הוא לכל חשבון ולכל Region. אם אתה משתמש בשלושה Regions, מגדירים אותו שלוש פעמים.' },
            { n: 2, en: 'The modalities to log. Embedding inputs can be huge document chunks, so think before you log them.', he: 'ה-modalities שרוצים לרשום. קלטי embedding יכולים להיות קטעי מסמכים ענקיים, אז חושבים לפני שרושמים אותם.' },
            { n: 3, en: 'With CloudWatch Logs you will also be asked for a log group and a service role, and you can add an S3 location for bodies over 100 KB.', he: 'עם CloudWatch Logs תתבקש גם לתת log group ו-service role, ואפשר להוסיף מיקום S3 לגופים מעל 100 KB.' }
          ],
          success: { en: 'Logging is on. From now on every Converse and InvokeModel call in this Region is saved with its full prompt and answer. That is powerful for debugging, and it is also a new store of user data that you must protect.', he: 'ה-logging דלוק. מעכשיו כל קריאת Converse ו-InvokeModel ב-Region הזה נשמרת עם הפרומפט והתשובה המלאים. זה חזק מאוד לדיבוג, וזה גם מאגר חדש של מידע משתמשים שחייבים להגן עליו.' },
          caption: { en: 'Simplified. Path: Amazon Bedrock console → Settings → Model invocation logging. The group headings may differ in the real console.', he: 'מפושט. הנתיב: הקונסול של Amazon Bedrock ← Settings ← Model invocation logging. כותרות הקבוצות עשויות להיות שונות בקונסול האמיתי.' } },
        { t: 'p', en: 'From code you use the `bedrock` client (the control plane, not `bedrock-runtime`). The API is `PutModelInvocationLoggingConfiguration`. For CloudWatch you must supply an IAM role that the Bedrock service (`bedrock.amazonaws.com`) can assume, with permission for `logs:CreateLogStream` and `logs:PutLogEvents`.', he: 'מהקוד משתמשים ב-client בשם `bedrock` (ה-control plane, לא `bedrock-runtime`). ה-API הוא `PutModelInvocationLoggingConfiguration`. בשביל CloudWatch צריך לספק IAM role שהשירות Bedrock (`bedrock.amazonaws.com`) יכול לקבל (assume), עם הרשאות `logs:CreateLogStream` ו-`logs:PutLogEvents`.' },
        { t: 'fill', prompt: { en: 'Enable invocation logging to a CloudWatch log group, text only.', he: 'הפעל invocation logging ל-log group ב-CloudWatch, טקסט בלבד.' },
          lang: 'python', code: 'import boto3\n\nbedrock = boto3.client("{{1}}")\nbedrock.put_model_invocation_logging_configuration(\n    loggingConfig={\n        "{{2}}": {\n            "logGroupName": "/bedrock/invocations",\n            "roleArn": "arn:aws:iam::111122223333:role/bedrock-logging",\n        },\n        "{{3}}": True,\n        "imageDataDeliveryEnabled": False,\n        "embeddingDataDeliveryEnabled": False,\n    }\n)',
          blanks: [ { accept: ['bedrock'], hint: { en: 'the control-plane client, not the runtime one', he: 'ה-client של ה-control plane, לא של ה-runtime' } }, { accept: ['cloudWatchConfig'], hint: { en: 'camelCase: the CloudWatch destination block', he: 'camelCase: בלוק היעד של CloudWatch' } }, { accept: ['textDataDeliveryEnabled'], hint: { en: 'the flag for the text modality', he: 'הדגל של modality הטקסט' } } ],
          explain: { en: 'Settings live on the `bedrock` control-plane client. `cloudWatchConfig` holds the log group and the role, and each modality has its own `...DataDeliveryEnabled` flag.', he: 'הגדרות נמצאות ב-client של ה-control plane בשם `bedrock`. `cloudWatchConfig` מחזיק את ה-log group ואת ה-role, ולכל modality יש דגל `...DataDeliveryEnabled` משלו.' } },
        { t: 'quiz', q: { en: 'Half of your traffic uses the Converse API on `bedrock-runtime`. The other half uses the Anthropic Messages API on `bedrock-mantle`. You enable model invocation logging. What do you get?', he: 'חצי מהתעבורה שלך משתמש ב-Converse API על `bedrock-runtime`. החצי השני משתמש ב-Anthropic Messages API על `bedrock-mantle`. אתה מפעיל model invocation logging. מה תקבל?' },
          options: { en: ['Logs for all the traffic', 'Logs only for the bedrock-runtime half', 'Logs only for the bedrock-mantle half', 'No logs until CloudTrail data events are enabled'], he: ['Logs לכל התעבורה', 'Logs רק לחצי של bedrock-runtime', 'Logs רק לחצי של bedrock-mantle', 'בלי logs עד שמפעילים data events ב-CloudTrail'] },
          answer: 1, explain: { en: 'Invocation logging does not capture requests sent to `bedrock-mantle`. If you need prompt-level logs for that traffic, your application must log it itself. CloudTrail is unrelated: it never stores prompt text.', he: 'Invocation logging לא לוכד בקשות שנשלחות ל-`bedrock-mantle`. אם צריך logs ברמת הפרומפט לתעבורה הזו, האפליקציה שלך צריכה לרשום אותם בעצמה. CloudTrail לא קשור: הוא אף פעם לא שומר טקסט של פרומפט.' } },
        { t: 'h', en: 'CloudWatch metrics for Bedrock', he: 'CloudWatch metrics של Bedrock' },
        { t: 'p', en: 'Bedrock publishes runtime metrics automatically in the [[Namespace]] `AWS/Bedrock`. The main [[Dimension]] is `ModelId`. Learn the exact names: you will type them into dashboards and alarms.', he: 'Bedrock מפרסם metrics של runtime אוטומטית ב-[[Namespace]] בשם `AWS/Bedrock`. ה-[[Dimension]] המרכזי הוא `ModelId`. כדאי להכיר את השמות המדויקים: תקליד אותם בדשבורדים וב-alarms.' },
        { t: 'table', head: { en: ['Metric', 'What it counts', 'The detail that trips people'], he: ['Metric', 'מה הוא סופר', 'הפרט שמפיל אנשים'] }, rows: {
          en: [
            ['`Invocations`', 'Requests accepted for processing.', 'Includes requests that fail later. Does **not** include throttled requests.'],
            ['`InvocationLatency`', 'Milliseconds from request sent to **last** token received.', 'A long answer makes it high even when the model is fast.'],
            ['`TimeToFirstToken`', 'Milliseconds until the first token.', 'Streaming operations only.'],
            ['`InvocationClientErrors` / `InvocationServerErrors`', 'Failed requests (your fault / service fault).', 'Quota-exceeded rejections count as **client errors**, not as throttles.'],
            ['`InvocationThrottles`', 'Throttled requests.', 'Not part of `Invocations`. The number depends on SDK retries, which can hide throttling from your code.'],
            ['`InputTokenCount` / `OutputTokenCount`', 'Tokens in and out.', 'This is your cost signal.'],
            ['`CacheReadInputTokenCount` / `CacheWriteInputTokenCount`', 'Prompt-caching tokens.', 'Cache reads do not count toward the TPM quota. Cache writes do.'],
            ['`EstimatedTPMQuotaUsage`', 'An estimate of tokens-per-minute quota use.', 'An approximation. Real throttling reserves input tokens + `max_tokens` up front.']
          ],
          he: [
            ['`Invocations`', 'בקשות שהתקבלו לעיבוד.', 'כולל בקשות שנכשלות אחר כך. **לא** כולל בקשות שקיבלו throttling.'],
            ['`InvocationLatency`', 'מילישניות משליחת הבקשה עד קבלת הטוקן **האחרון**.', 'תשובה ארוכה מעלה אותו גם כשהמודל מהיר.'],
            ['`TimeToFirstToken`', 'מילישניות עד הטוקן הראשון.', 'רק בפעולות streaming.'],
            ['`InvocationClientErrors` / `InvocationServerErrors`', 'בקשות שנכשלו (באשמתך / באשמת השירות).', 'דחיות בגלל חריגה מ-quota נספרות כ-**client errors**, לא כ-throttles.'],
            ['`InvocationThrottles`', 'בקשות שקיבלו throttling.', 'לא חלק מ-`Invocations`. המספר תלוי ב-retries של ה-SDK, שיכולים להסתיר throttling מהקוד שלך.'],
            ['`InputTokenCount` / `OutputTokenCount`', 'טוקנים נכנסים ויוצאים.', 'זה אות העלות שלך.'],
            ['`CacheReadInputTokenCount` / `CacheWriteInputTokenCount`', 'טוקנים של prompt caching.', 'Cache reads לא נספרים ב-quota של TPM. Cache writes כן.'],
            ['`EstimatedTPMQuotaUsage`', 'הערכה של ניצול ה-quota של טוקנים לדקה.', 'קירוב בלבד. ה-throttling האמיתי שומר מראש טוקני קלט + `max_tokens`.']
          ] } },
        { t: 'note', kind: 'warn', en: 'Metrics are published both with and without the `ModelId` dimension. A request that fails **before** Bedrock resolves the model has no `ModelId`. So if your error alarm filters by one model, it can miss errors. For error and throttle alarms, also watch the series without the dimension.', he: 'Metrics מתפרסמים גם עם ה-dimension בשם `ModelId` וגם בלעדיו. לבקשה שנכשלת **לפני** ש-Bedrock מזהה את המודל אין `ModelId`. לכן אם ה-alarm שלך על שגיאות מסנן לפי מודל אחד, הוא יכול לפספס שגיאות. ל-alarms על שגיאות ו-throttles, עקוב גם אחרי הסדרה בלי ה-dimension.' },
        { t: 'p', en: 'Other Bedrock features have their own namespaces. Guardrails publish to `AWS/Bedrock/Guardrails` (for example `InvocationsIntervened`). Bedrock Agents Classic publish to `AWS/Bedrock/Agents`. The newer `bedrock-mantle` endpoint has its own namespace `AWS/BedrockMantle` with fewer metrics: today it has no latency metric, and 429 throttling is not a metric there, so you track those in your application.', he: 'ליכולות אחרות של Bedrock יש namespaces משלהן. Guardrails מפרסמים ל-`AWS/Bedrock/Guardrails` (למשל `InvocationsIntervened`). Bedrock Agents Classic מפרסמים ל-`AWS/Bedrock/Agents`. ל-endpoint החדש יותר `bedrock-mantle` יש namespace משלו `AWS/BedrockMantle` עם פחות metrics: היום אין בו metric של latency, ו-throttling מסוג 429 הוא לא metric שם, ולכן עוקבים אחריהם באפליקציה.' },
        { t: 'p', en: 'You do not have to build the first dashboard yourself. In the CloudWatch console, **GenAI Observability** has a pre-built **Model Invocations** view. It works with any Bedrock model and appears once you invoke models: invocation count, latency, token counts by model, throttles and errors. The table that shows the input and output **content** of each call needs model invocation logging sent to CloudWatch Logs.', he: 'לא חייבים לבנות את הדשבורד הראשון לבד. בקונסול של CloudWatch, תחת **GenAI Observability**, יש תצוגה מוכנה בשם **Model Invocations**. היא עובדת עם כל מודל Bedrock ומופיעה ברגע שקוראים למודלים: מספר קריאות, latency, טוקנים לפי מודל, throttles ושגיאות. הטבלה שמציגה את **תוכן** הקלט והפלט של כל קריאה דורשת model invocation logging שנשלח ל-CloudWatch Logs.' },
        { t: 'quiz', q: { en: 'Users complain about errors, but your dashboard shows `InvocationThrottles` = 0. The SDK retries automatically, and `InvocationClientErrors` is climbing. What is a likely explanation?', he: 'משתמשים מתלוננים על שגיאות, אבל הדשבורד מראה `InvocationThrottles` = 0. ה-SDK עושה retries אוטומטית, ו-`InvocationClientErrors` מטפס. מה הסבר סביר?' },
          options: { en: ['The metric is broken in this Region', 'Throttles are only counted for streaming calls', 'Requests are being rejected for exceeding a quota, and those rejections are counted as client errors', 'CloudTrail must be enabled before throttles are counted'], he: ['ה-metric שבור ב-Region הזה', 'Throttles נספרים רק בקריאות streaming', 'בקשות נדחות בגלל חריגה מ-quota, והדחיות האלה נספרות כ-client errors', 'צריך להפעיל CloudTrail לפני ש-throttles נספרים'] },
          answer: 2, explain: { en: 'Quota-exceeded rejections are counted in `InvocationClientErrors`, not in `InvocationThrottles`. A pro watches both, plus `EstimatedTPMQuotaUsage`, before concluding "we are not being throttled".', he: 'דחיות בגלל חריגה מ-quota נספרות ב-`InvocationClientErrors`, לא ב-`InvocationThrottles`. מקצוען עוקב אחרי שניהם, ועוד `EstimatedTPMQuotaUsage`, לפני שהוא מסיק "אין לנו throttling".' } },
        { t: 'h', en: 'CloudTrail: who did what', he: 'CloudTrail: מי עשה מה' },
        { t: 'p', en: '[[CloudTrail]] is the audit log of AWS. For Bedrock the event source is `bedrock.amazonaws.com`. Model calls (`InvokeModel`, `Converse` and their streaming versions) and all control-plane calls are logged as **management events**, which are on by default. CloudTrail records the caller, the time, the source IP and parameters such as the model ID. It does **not** record the prompt.', he: '[[CloudTrail]] הוא יומן הביקורת של AWS. עבור Bedrock ה-event source הוא `bedrock.amazonaws.com`. קריאות למודל (`InvokeModel`, `Converse` וגרסאות ה-streaming שלהן) וכל קריאות ה-control plane נרשמות כ-**management events**, שדלוקים כברירת מחדל. CloudTrail רושם את הקורא, הזמן, כתובת ה-IP ופרמטרים כמו מזהה המודל. הוא **לא** רושם את הפרומפט.' },
        { t: 'list', en: [
          '**Data events** are off by default and cost extra. They cover higher-level calls such as `InvokeAgent`, `Retrieve`, `RetrieveAndGenerate`, `InvokeFlow` and `ApplyGuardrail`.',
          '**Streaming calls create two events.** After the stream ends there is a second event with the same `eventName` but `eventType` = `AwsServiceEvent`. It carries `inferenceRegion`, `inputTokens` and `outputTokens`. To count invocations, count only `eventType = AwsApiCall`.',
          '**Cross-Region inference:** the event is logged in the Region you called from. The field `additionalEventData.inferenceRegion` shows where the model really ran.',
          '**Who changed the settings?** Someone turned off invocation logging or edited a guardrail last night. That is a control-plane call, and CloudTrail has it.'
        ], he: [
          '**Data events** כבויים כברירת מחדל ועולים כסף נוסף. הם מכסים קריאות ברמה גבוהה יותר כמו `InvokeAgent`, `Retrieve`, `RetrieveAndGenerate`, `InvokeFlow` ו-`ApplyGuardrail`.',
          '**קריאות streaming יוצרות שני אירועים.** אחרי שה-stream נגמר יש אירוע שני עם אותו `eventName` אבל `eventType` = `AwsServiceEvent`. הוא נושא `inferenceRegion`, `inputTokens` ו-`outputTokens`. כדי לספור קריאות, סופרים רק `eventType = AwsApiCall`.',
          '**Cross-Region inference:** האירוע נרשם ב-Region שממנו קראת. השדה `additionalEventData.inferenceRegion` מראה איפה המודל באמת רץ.',
          '**מי שינה את ההגדרות?** מישהו כיבה invocation logging או ערך guardrail אתמול בלילה. זו קריאת control plane, והיא נמצאת ב-CloudTrail.'
        ] },
        { t: 'match', prompt: { en: 'Where do you look? Match the question to the source.', he: 'איפה מחפשים? התאם את השאלה למקור.' }, pairs: [
          { a: { en: 'What was the exact prompt that produced this bad answer?', he: 'מה היה הפרומפט המדויק שהוביל לתשובה הגרועה הזו?' }, b: 'Model invocation logging' },
          { a: { en: 'Which IAM role deleted the guardrail yesterday?', he: 'איזה IAM role מחק את ה-guardrail אתמול?' }, b: 'CloudTrail' },
          { a: { en: 'Did latency get worse after 14:00?', he: 'האם ה-latency החמיר אחרי 14:00?' }, b: { en: 'CloudWatch metric InvocationLatency', he: 'CloudWatch metric בשם InvocationLatency' } },
          { a: { en: 'In which Region did this cross-Region call really run?', he: 'באיזה Region הקריאה הזו (cross-Region) באמת רצה?' }, b: { en: 'CloudTrail field inferenceRegion', he: 'השדה inferenceRegion ב-CloudTrail' } },
          { a: { en: 'How long do users wait for the first word?', he: 'כמה זמן משתמשים מחכים למילה הראשונה?' }, b: { en: 'CloudWatch metric TimeToFirstToken', he: 'CloudWatch metric בשם TimeToFirstToken' } }
        ] },
        { t: 'quiz', q: { en: 'The security team asks: "Prove which principal called Claude at 03:12 last night, and from which IP." Model invocation logging was never enabled. Can you answer?', he: 'צוות האבטחה שואל: "תוכיח איזה principal קרא ל-Claude ב-03:12 אתמול בלילה, ומאיזה IP." Model invocation logging מעולם לא הופעל. האם אפשר לענות?' },
          options: { en: ['No, without invocation logging nothing was recorded', 'Only if the call was a streaming call', 'Only by asking AWS Support for the prompt', 'Yes, CloudTrail logs model invocations as management events by default'], he: ['לא, בלי invocation logging שום דבר לא נרשם', 'רק אם הקריאה הייתה קריאת streaming', 'רק אם מבקשים מ-AWS Support את הפרומפט', 'כן, CloudTrail רושם קריאות למודל כ-management events כברירת מחדל'] },
          answer: 3, explain: { en: 'CloudTrail records who, when, from where and which model, by default. What you cannot recover is the prompt text: that needed invocation logging, which was off.', he: 'CloudTrail רושם מי, מתי, מאיפה ואיזה מודל, כברירת מחדל. מה שאי אפשר לשחזר הוא טקסט הפרומפט: בשביל זה היה צריך invocation logging, שהיה כבוי.' } },
        { t: 'reveal', q: { en: 'Interview question: "Would you turn on model invocation logging in production? What are the trade-offs?"', he: 'שאלת ראיון: "היית מדליק model invocation logging בפרודקשן? מה ה-trade-offs?"' },
          a: { en: 'Usually yes, but on purpose and with controls. Benefits: I can see the exact prompt and answer for any bad result, build evaluation sets from real traffic, and attribute tokens by caller and by request metadata. Costs and risks: it stores user content, so the log group or bucket becomes sensitive data. I would restrict access with IAM, encrypt it, set a retention period, mask PII before it reaches the model where possible, and check that it fits our privacy commitments. I would also remember its limits: it is per Region, it does not cover bedrock-mantle, and large bodies need an S3 location.', he: 'בדרך כלל כן, אבל בכוונה ועם בקרות. יתרונות: אפשר לראות את הפרומפט והתשובה המדויקים לכל תוצאה גרועה, לבנות סטים ל-evaluation מתעבורה אמיתית, ולייחס טוקנים לפי קורא ולפי request metadata. עלויות וסיכונים: זה שומר תוכן של משתמשים, ולכן ה-log group או ה-bucket הופכים למידע רגיש. הייתי מגביל גישה עם IAM, מצפין, קובע retention, ממסך PII לפני שהוא מגיע למודל כשאפשר, ובודק שזה מתאים להתחייבויות הפרטיות שלנו. הייתי גם זוכר את המגבלות: זה לכל Region בנפרד, זה לא מכסה את bedrock-mantle, וגופים גדולים צריכים מיקום S3.' } }
      ]
    },
    {
      id: 'm12l4', minutes: 14,
      title: { en: 'Dashboards and alarms for day one', he: 'דשבורדים ו-alarms ליום הראשון' },
      blocks: [
        { t: 'p', en: 'A junior developer adds monitoring after the first incident. A pro ships the dashboard and the [[Alarm]]s **together with** the feature. This lesson is the list a pro sets up on day one, and the reasons behind each item.', he: 'מפתח מתחיל מוסיף ניטור אחרי התקלה הראשונה. מקצוען מעלה את הדשבורד ואת ה-[[Alarm]]s **יחד עם** הפיצ׳ר. השיעור הזה הוא הרשימה שמקצוען מקים ביום הראשון, והסיבות מאחורי כל פריט.' },
        { t: 'h', en: 'First: averages lie. Use percentiles', he: 'קודם כול: ממוצעים משקרים. משתמשים ב-percentiles' },
        { t: 'p', en: 'Sort all request durations from fast to slow. The [[Percentile]] **p50** (the median) is the value in the middle: half of the requests are faster. **p95** is the value that 95% of requests are faster than. **p99** is the same for 99%. p95 and p99 describe your unlucky users. An average mixes everybody together and hides them.', he: 'ממיינים את כל משכי הבקשות מהמהיר לאיטי. ה-[[Percentile]] בשם **p50** (החציון) הוא הערך שבאמצע: חצי מהבקשות מהירות ממנו. **p95** הוא הערך ש-95% מהבקשות מהירות ממנו. **p99** אותו דבר ל-99%. p95 ו-p99 מתארים את המשתמשים חסרי המזל שלך. ממוצע מערבב את כולם ומסתיר אותם.' },
        { t: 'code', lang: 'text', code: '100 requests:  94 take 2 s,  6 take 30 s (the agent looped)\n\naverage = (94 x 2 + 6 x 30) / 100 = 3.68 s   "looks fine"\np50     = 2 s                                "typical user is happy"\np95     = 30 s                               "1 in 20 users waits half a minute"', caption: { en: 'The average hides the loop. p95 shows it at once.', he: 'הממוצע מסתיר את הלולאה. p95 מראה אותה מיד.' } },
        { t: 'note', kind: 'tip', en: 'Agents have a "long tail" by nature: most turns need one or two steps, some need ten. So for agents always chart p50 **and** p95 (or p99) side by side. When p50 is flat and p95 climbs, a subset of requests is in trouble: one tool, one tenant, one type of question.', he: 'לסוכנים יש "זנב ארוך" מטבעם: רוב התורות צריכים צעד או שניים, חלק צריכים עשרה. לכן בסוכנים תמיד מציירים p50 **וגם** p95 (או p99) זה לצד זה. כש-p50 שטוח ו-p95 מטפס, תת-קבוצה של בקשות בצרות: כלי אחד, tenant אחד, סוג שאלה אחד.' },
        { t: 'quiz', q: { en: 'Out of 200 requests, 180 take 1 second and 20 take 21 seconds. Which statement is true?', he: 'מתוך 200 בקשות, 180 לוקחות שנייה אחת ו-20 לוקחות 21 שניות. איזה משפט נכון?' },
          options: { en: ['The average is 3 s, p50 is 1 s and p95 is 21 s', 'The average is 1 s, p50 is 1 s and p95 is 1 s', 'The average is 11 s, p50 is 11 s and p95 is 21 s', 'The average is 3 s, p50 is 3 s and p95 is 3 s'], he: ['הממוצע 3 שניות, p50 הוא שנייה ו-p95 הוא 21 שניות', 'הממוצע שנייה, p50 שנייה ו-p95 שנייה', 'הממוצע 11 שניות, p50 הוא 11 שניות ו-p95 הוא 21 שניות', 'הממוצע 3 שניות, p50 הוא 3 שניות ו-p95 הוא 3 שניות'] },
          answer: 0, explain: { en: 'Average = (180 x 1 + 20 x 21) / 200 = 600 / 200 = 3 s. The middle request takes 1 s, so p50 = 1 s. The slowest 10% take 21 s, so the 95th percentile falls inside them: 21 s. Three numbers, three very different stories.', he: 'ממוצע = (180 x 1 + 20 x 21) / 200 = 600 / 200 = 3 שניות. הבקשה האמצעית לוקחת שנייה, ולכן p50 = שנייה. 10% האיטיות לוקחות 21 שניות, ולכן האחוזון ה-95 נופל בתוכן: 21 שניות. שלושה מספרים, שלושה סיפורים שונים לגמרי.' } },
        { t: 'h', en: 'The day-one dashboard', he: 'הדשבורד של היום הראשון' },
        { t: 'table', head: { en: ['Panel', 'Source', 'Why it is there'], he: ['פאנל', 'מקור', 'למה הוא שם'] }, rows: {
          en: [
            ['Latency p50 / p95 / p99', '`InvocationLatency` (`AWS/Bedrock`), `Latency` (`AWS/Bedrock-AgentCore`)', 'User experience. Split model latency from whole-agent latency.'],
            ['Time to first token', '`TimeToFirstToken`', 'What a streaming user actually feels.'],
            ['Error rate', '`InvocationClientErrors` + `InvocationServerErrors` divided by `Invocations`; Runtime `System Errors`, `User Errors`', 'A rate, not a count, so traffic growth does not look like a problem.'],
            ['Throttle rate', '`InvocationThrottles`, `EstimatedTPMQuotaUsage`; Runtime `Throttles`', 'Early warning that you are near a quota.'],
            ['Tokens in / out', '`InputTokenCount`, `OutputTokenCount`, cache read / write counts', 'Cost. A jump in input tokens per request usually means a prompt or history problem.'],
            ['Cost per feature / tenant', '[[Application inference profile]] tags, [[Request metadata]] in invocation logs', 'Who is spending the money.'],
            ['Guardrail intervention rate', '`InvocationsIntervened` divided by `Invocations` in `AWS/Bedrock/Guardrails`', 'Attack, misuse, or a guardrail that is too strict.'],
            ['Tool failure rate', 'Tool spans with an error status, Gateway logs', 'The most common hidden cause of bad answers.'],
            ['Sessions and compute', '`ActiveSessionCount`, `CPUUsed-vCPUHours`, `MemoryUsed-GBHours`', 'Capacity against quotas, and Runtime cost.'],
            ['Quality scores', 'AgentCore Evaluations results (namespace `Bedrock-AgentCore/Evaluations`)', 'The only panel that says if answers are **good**, not just fast.']
          ],
          he: [
            ['Latency ב-p50 / p95 / p99', '`InvocationLatency` (`AWS/Bedrock`), `Latency` (`AWS/Bedrock-AgentCore`)', 'חוויית משתמש. מפרידים בין latency של המודל ל-latency של כל הסוכן.'],
            ['הזמן עד הטוקן הראשון', '`TimeToFirstToken`', 'מה שמשתמש streaming באמת מרגיש.'],
            ['שיעור שגיאות', '`InvocationClientErrors` + `InvocationServerErrors` חלקי `Invocations`; ב-Runtime: `System Errors`, `User Errors`', 'שיעור ולא ספירה, כדי שגידול בתעבורה לא ייראה כמו בעיה.'],
            ['שיעור throttling', '`InvocationThrottles`, `EstimatedTPMQuotaUsage`; ב-Runtime: `Throttles`', 'אזהרה מוקדמת שאתה קרוב ל-quota.'],
            ['טוקנים נכנסים / יוצאים', '`InputTokenCount`, `OutputTokenCount`, ספירות cache read / write', 'עלות. קפיצה בטוקני קלט לבקשה אומרת בדרך כלל בעיה בפרומפט או בהיסטוריה.'],
            ['עלות לפי פיצ׳ר / tenant', 'תגים של [[Application inference profile]], [[Request metadata]] ב-invocation logs', 'מי מוציא את הכסף.'],
            ['שיעור התערבות של guardrail', '`InvocationsIntervened` חלקי `Invocations` ב-`AWS/Bedrock/Guardrails`', 'התקפה, שימוש לרעה, או guardrail קשוח מדי.'],
            ['שיעור כישלון כלים', 'Spans של כלים עם סטטוס שגיאה, logs של Gateway', 'הסיבה הנסתרת הנפוצה ביותר לתשובות גרועות.'],
            ['Sessions ומשאבי חישוב', '`ActiveSessionCount`, `CPUUsed-vCPUHours`, `MemoryUsed-GBHours`', 'קיבולת מול quotas, ועלות Runtime.'],
            ['ציוני איכות', 'תוצאות AgentCore Evaluations (namespace בשם `Bedrock-AgentCore/Evaluations`)', 'הפאנל היחיד שאומר אם התשובות **טובות**, לא רק מהירות.']
          ] } },
        { t: 'note', kind: 'jargon', en: 'The Guardrails namespace has useful [[Dimension]]s: `GuardrailPolicyType` (ContentPolicy, TopicPolicy, WordPolicy, SensitiveInformationPolicy, ContextualGroundingPolicy) and `GuardrailContentSource` (Input or Output). So you can see not only "how often did it intervene" but "which policy fired, and on the user side or the model side".', he: 'ל-namespace של Guardrails יש [[Dimension]]s שימושיים: `GuardrailPolicyType` (ContentPolicy, TopicPolicy, WordPolicy, SensitiveInformationPolicy, ContextualGroundingPolicy) ו-`GuardrailContentSource` (Input או Output). כך רואים לא רק "כמה פעמים הוא התערב" אלא "איזו policy הופעלה, ובצד המשתמש או בצד המודל".' },
        { t: 'h', en: 'Cost per feature and per tenant', he: 'עלות לפי פיצ׳ר ולפי tenant' },
        { t: 'p', en: 'The AWS bill says "Bedrock: $9,400". Your manager asks "which feature?" and "which customer?". By default you cannot answer, because all calls look the same. There are three tools for runtime traffic, and each shows up in a different place.', he: 'בחשבון AWS כתוב "Bedrock: $9,400". המנהל שואל "איזה פיצ׳ר?" ו"איזה לקוח?". כברירת מחדל אי אפשר לענות, כי כל הקריאות נראות אותו דבר. יש שלושה כלים לתעבורת runtime, וכל אחד מופיע במקום אחר.' },
        { t: 'table', head: { en: ['Tool', 'How it works', 'Where the answer appears', 'Limits'], he: ['כלי', 'איך זה עובד', 'איפה התשובה מופיעה', 'מגבלות'] }, rows: {
          en: [
            ['[[Application inference profile]]', 'Create a tagged profile per feature or team and pass its ARN as `modelId`.', 'Cost Explorer and cost reports, **in dollars**.', 'Works with InvokeModel and Converse on `bedrock-runtime`. Tags must be activated as cost allocation tags: up to 24 hours, not retroactive.'],
            ['IAM principal attribution', 'The caller identity is captured automatically. Add tags on the role or as session tags.', 'Cost Explorer and CUR 2.0.', 'Needs a different role or session per thing you want to separate.'],
            ['[[Request metadata]]', 'Attach key-value tags to each call (`requestMetadata` in Converse).', 'Model invocation logs **only**. You compute tokens with a query.', 'Up to 16 entries, keys and values up to 256 characters. Needs invocation logging on. Never appears in Cost Explorer.']
          ],
          he: [
            ['[[Application inference profile]]', 'יוצרים profile מתויג לכל פיצ׳ר או צוות ומעבירים את ה-ARN שלו כ-`modelId`.', 'Cost Explorer ודוחות עלות, **בדולרים**.', 'עובד עם InvokeModel ו-Converse על `bedrock-runtime`. צריך להפעיל את התגים כ-cost allocation tags: עד 24 שעות, לא רטרואקטיבי.'],
            ['IAM principal attribution', 'זהות הקורא נלכדת אוטומטית. מוסיפים תגים על ה-role או כ-session tags.', 'Cost Explorer ו-CUR 2.0.', 'צריך role או session שונה לכל דבר שרוצים להפריד.'],
            ['[[Request metadata]]', 'מצמידים תגי מפתח-ערך לכל קריאה (`requestMetadata` ב-Converse).', 'ב-model invocation logs **בלבד**. מחשבים טוקנים עם שאילתה.', 'עד 16 רשומות, מפתחות וערכים עד 256 תווים. דורש invocation logging דלוק. אף פעם לא מופיע ב-Cost Explorer.']
          ] } },
        { t: 'code', lang: 'python', code: 'import boto3\n\nbedrock = boto3.client("bedrock", region_name="us-east-1")\narn = bedrock.create_inference_profile(\n    inferenceProfileName="team-growth-sonnet",\n    modelSource={"copyFrom": "arn:aws:bedrock:us-east-1:123456789012:inference-profile/us.anthropic.claude-sonnet-4-20250514-v1:0"},\n    tags=[{"key": "team", "value": "growth"}],\n)["inferenceProfileArn"]\n\nruntime = boto3.client("bedrock-runtime", region_name="us-east-1")\nruntime.converse(\n    modelId=arn,   # the profile ARN instead of a model ID\n    messages=[{"role": "user", "content": [{"text": "Hello"}]}],\n)', caption: { en: 'An application inference profile: created once on the control plane, then used as modelId.', he: 'Application inference profile: נוצר פעם אחת ב-control plane, ואז משמש כ-modelId.' } },
        { t: 'fill', prompt: { en: 'You have 400 tenants. A profile per tenant is too many resources, so you tag each call instead. Add the tenant and the feature to this Converse call so they appear in the invocation logs.', he: 'יש לך 400 tenants. Profile לכל tenant זה יותר מדי משאבים, אז מתייגים כל קריאה. הוסף את ה-tenant ואת הפיצ׳ר לקריאת ה-Converse הזו כך שיופיעו ב-invocation logs.' },
          lang: 'python', code: 'runtime.converse(\n    modelId="us.anthropic.claude-sonnet-5-5",\n    messages=messages,\n    {{1}}={"tenant": "acme", "feature": "order-status"},\n)',
          blanks: [ { accept: ['requestMetadata'], hint: { en: 'camelCase: metadata of the request', he: 'camelCase: ה-metadata של הבקשה' } } ],
          explain: { en: '`requestMetadata` is written into each invocation log record. Then a Logs Insights query can sum tokens by tenant. Remember that it lives only in the logs, not in the bill.', he: '`requestMetadata` נכתב לכל רשומת invocation log. אחר כך שאילתת Logs Insights יכולה לסכם טוקנים לפי tenant. זכור שהוא חי רק ב-logs, לא בחשבונית.' } },
        { t: 'h', en: 'A Logs Insights query', he: 'שאילתת Logs Insights' },
        { t: 'p', en: '[[Logs Insights]] is the query tool of CloudWatch Logs. A query is a chain of commands joined by `|`: pick fields, filter, compute statistics, sort. This one runs on the invocation log group and answers "which tenant used the most tokens, per feature?".', he: '[[Logs Insights]] הוא כלי השאילתות של CloudWatch Logs. שאילתה היא שרשרת פקודות שמחוברות ב-`|`: בוחרים שדות, מסננים, מחשבים סטטיסטיקות, ממיינים. השאילתה הזו רצה על ה-log group של invocation logs ועונה על "איזה tenant השתמש בהכי הרבה טוקנים, לפי פיצ׳ר?".' },
        { t: 'code', lang: 'text', code: 'fields @timestamp, modelId, requestMetadata.tenant, requestMetadata.feature\n| filter operation = "Converse"\n| stats count(*) as calls,\n        sum(input.inputTokenCount) as inputTokens,\n        sum(output.outputTokenCount) as outputTokens\n  by requestMetadata.tenant, requestMetadata.feature\n| sort inputTokens desc\n| limit 20', caption: { en: 'Field paths follow the invocation log schema from the previous lesson. Test the query on your own log group before you rely on it.', he: 'נתיבי השדות לפי סכמת ה-invocation log מהשיעור הקודם. בדוק את השאילתה על ה-log group שלך לפני שאתה מסתמך עליה.' } },
        { t: 'fill', prompt: { en: 'Complete the query: the 10 single calls with the most input tokens in the selected time range, so you can find runaway prompts.', he: 'השלם את השאילתה: 10 הקריאות הבודדות עם הכי הרבה טוקני קלט בטווח הזמן שנבחר, כדי למצוא פרומפטים שיצאו משליטה.' },
          lang: 'text', code: 'fields @timestamp, requestId, modelId, input.inputTokenCount\n| {{1}} input.inputTokenCount desc\n| {{2}} 10',
          blanks: [ { accept: ['sort'], hint: { en: 'order the results', he: 'סידור התוצאות' } }, { accept: ['limit'], hint: { en: 'keep only the first N', he: 'להשאיר רק את N הראשונות' } } ],
          explain: { en: '`sort ... desc` puts the biggest first and `limit 10` keeps the top ten. Take a `requestId` from the result and open that record to read the full prompt.', he: '`sort ... desc` שם את הגדולות ראשונות ו-`limit 10` משאיר את עשר הראשונות. קח `requestId` מהתוצאה ופתח את הרשומה הזו כדי לקרוא את הפרומפט המלא.' } },
        { t: 'h', en: 'Alarms: what should wake you up', he: 'Alarms: מה צריך להעיר אותך' },
        { t: 'p', en: 'A dashboard only works when somebody looks at it. An [[Alarm]] watches a metric for you. Two rules make alarms useful instead of noisy: alarm on **rates and percentiles**, not on raw counts, and require the condition to hold for **several periods in a row**, so that one bad minute does not page anybody.', he: 'דשבורד עובד רק כשמישהו מסתכל עליו. [[Alarm]] עוקב אחרי metric בשבילך. שני כללים הופכים alarms לשימושיים ולא לרועשים: מגדירים alarm על **שיעורים ו-percentiles**, לא על ספירות גולמיות, ודורשים שהתנאי יתקיים **כמה פרקי זמן ברצף**, כדי שדקה גרועה אחת לא תעיר אף אחד.' },
        { t: 'table', head: { en: ['Alarm', 'Starting threshold (tune it to your baseline)', 'What it usually means'], he: ['Alarm', 'סף התחלתי (לכוון לפי ה-baseline שלך)', 'מה זה אומר בדרך כלל'] }, rows: {
          en: [
            ['Agent latency p95', 'Above about 2x your normal p95 for 3 periods of 5 minutes', 'A slow tool, a slow model, or longer loops.'],
            ['Error rate', 'Above 2–5% for 5 minutes', 'A bad deploy, a broken tool, expired permissions.'],
            ['Throttle rate', 'Any sustained throttling, or estimated quota use above about 80%', 'You are at the quota. Act before users feel it.'],
            ['Tokens per request', 'Average input tokens per call up 50% against last week', 'Prompt or history growth, a tool returning huge results.'],
            ['Daily spend', 'A budget threshold per feature or tenant', 'A loop, abuse, or real growth. All three need a human.'],
            ['Guardrail intervention rate', 'A sudden jump against the normal rate', 'An attack, or a change that made the guardrail too strict.'],
            ['Log delivery failures', '`ModelInvocationLogsCloudWatchDeliveryFailure` above 0', 'Your invocation logs are silently not arriving.']
          ],
          he: [
            ['Latency של הסוכן ב-p95', 'מעל בערך פי 2 מה-p95 הרגיל במשך 3 פרקי זמן של 5 דקות', 'כלי איטי, מודל איטי, או לולאות ארוכות יותר.'],
            ['שיעור שגיאות', 'מעל 2–5% במשך 5 דקות', 'Deploy גרוע, כלי שבור, הרשאות שפגו.'],
            ['שיעור throttling', 'כל throttling מתמשך, או ניצול quota מוערך מעל בערך 80%', 'אתה ב-quota. פועלים לפני שהמשתמשים מרגישים.'],
            ['טוקנים לבקשה', 'ממוצע טוקני קלט לקריאה עלה ב-50% לעומת השבוע שעבר', 'גידול בפרומפט או בהיסטוריה, כלי שמחזיר תוצאות ענקיות.'],
            ['הוצאה יומית', 'סף תקציב לכל פיצ׳ר או tenant', 'לולאה, שימוש לרעה, או גידול אמיתי. שלושתם דורשים בן אדם.'],
            ['שיעור התערבות של guardrail', 'קפיצה פתאומית מול השיעור הרגיל', 'התקפה, או שינוי שהפך את ה-guardrail לקשוח מדי.'],
            ['כישלונות במסירת logs', '`ModelInvocationLogsCloudWatchDeliveryFailure` מעל 0', 'ה-invocation logs שלך לא מגיעים, בשקט.']
          ] } },
        { t: 'note', kind: 'warn', en: 'The thresholds above are engineering starting points, not AWS numbers. Run for a week, look at your real baseline, then set them. An alarm that fires every day is ignored within a week, and then it is worse than no alarm.', he: 'הספים למעלה הם נקודות התחלה הנדסיות, לא מספרים של AWS. מריצים שבוע, מסתכלים על ה-baseline האמיתי, ואז קובעים אותם. Alarm שנדלק כל יום זוכה להתעלמות תוך שבוע, ואז הוא גרוע יותר מאין alarm.' },
        { t: 'quiz', q: { en: 'Your alarm is "more than 50 model errors in 5 minutes". After a successful marketing campaign traffic is 10 times higher, and the alarm fires all day although the product works fine. What is the right fix?', he: 'ה-alarm שלך הוא "יותר מ-50 שגיאות מודל ב-5 דקות". אחרי קמפיין שיווקי מוצלח התעבורה גדולה פי 10, וה-alarm נדלק כל היום למרות שהמוצר עובד מצוין. מה התיקון הנכון?' },
          options: { en: ['Delete the alarm', 'Alarm on the error rate (errors divided by invocations) instead of the raw count', 'Raise the threshold to 5,000 errors', 'Turn off model invocation logging'], he: ['למחוק את ה-alarm', 'להגדיר alarm על שיעור השגיאות (שגיאות חלקי invocations) במקום על הספירה הגולמית', 'להעלות את הסף ל-5,000 שגיאות', 'לכבות model invocation logging'] },
          answer: 1, explain: { en: 'A count grows with traffic. A rate does not. 50 errors out of 1,000 calls (5%) is a problem; 50 out of 100,000 (0.05%) is normal noise. Raising the count to 5,000 just breaks the alarm again the next time traffic changes.', he: 'ספירה גדלה עם התעבורה. שיעור לא. 50 שגיאות מתוך 1,000 קריאות (5%) זו בעיה; 50 מתוך 100,000 (0.05%) זה רעש רגיל. העלאת הסף ל-5,000 רק שוברת את ה-alarm שוב בפעם הבאה שהתעבורה משתנה.' } },
        { t: 'quiz', q: { en: 'Finance wants a monthly report **in dollars** per product team for Bedrock usage, straight from Cost Explorer. Which mechanism gives that?', he: 'מחלקת הכספים רוצה דוח חודשי **בדולרים** לכל צוות מוצר על השימוש ב-Bedrock, ישר מ-Cost Explorer. איזה מנגנון נותן את זה?' },
          options: { en: ['requestMetadata on every call', 'A CloudWatch alarm per team', 'An application inference profile per team, with a team tag activated as a cost allocation tag', 'CloudTrail data events'], he: ['requestMetadata על כל קריאה', 'CloudWatch alarm לכל צוות', 'Application inference profile לכל צוות, עם תג team שהופעל כ-cost allocation tag', 'Data events של CloudTrail'] },
          answer: 2, explain: { en: 'Profile tags flow into Cost Explorer once they are activated as cost allocation tags (up to 24 hours, not retroactive). `requestMetadata` is tempting but it exists only in invocation logs and never reaches billing data.', he: 'תגים של profile זורמים ל-Cost Explorer אחרי שמפעילים אותם כ-cost allocation tags (עד 24 שעות, לא רטרואקטיבי). `requestMetadata` מפתה, אבל הוא קיים רק ב-invocation logs ואף פעם לא מגיע לנתוני החיוב.' } },
        { t: 'quiz', q: { en: 'The guardrail intervention rate jumps from 1% to 18% in one hour. Nothing was deployed. Which split of the metric do you check first to understand it?', he: 'שיעור ההתערבות של ה-guardrail קופץ מ-1% ל-18% בשעה אחת. לא הועלה שום דבר. איזה פילוח של ה-metric בודקים קודם כדי להבין?' },
          options: { en: ['By AWS account ID', 'By output image size', 'By context window size', 'By policy type and by content source (input or output)'], he: ['לפי מזהה חשבון AWS', 'לפי גודל תמונת הפלט', 'לפי גודל ה-context window', 'לפי סוג ה-policy ולפי מקור התוכן (input או output)'] },
          answer: 3, explain: { en: '`GuardrailPolicyType` and `GuardrailContentSource` tell you what is being caught and on which side. Many input-side content or prompt-attack hits with no deploy suggests an attack or abuse. Output-side hits suggest the model started producing something new.', he: '`GuardrailPolicyType` ו-`GuardrailContentSource` אומרים מה נתפס ובאיזה צד. הרבה פגיעות בצד ה-input (content או prompt attack) בלי deploy מרמזות על התקפה או שימוש לרעה. פגיעות בצד ה-output מרמזות שהמודל התחיל לייצר משהו חדש.' } },
        { t: 'order', prompt: { en: 'An alarm fires at night: "agent p95 latency high". Put the investigation steps in the order a pro follows.', he: 'Alarm נדלק בלילה: "p95 latency של הסוכן גבוה". סדר את שלבי החקירה לפי הסדר שמקצוען עובד.' }, items: { en: ['Look at the metric: when did it start, and is it all traffic or a part', 'Compare model latency with whole-agent latency to see which side grew', 'Open a few slow traces from that time window', 'Find the span that takes the time', 'Read the logs of that span or tool', 'Fix, then watch the metric return to normal'], he: ['להסתכל על ה-metric: מתי זה התחיל, והאם זו כל התעבורה או חלק', 'להשוות latency של המודל ל-latency של כל הסוכן כדי לראות איזה צד גדל', 'לפתוח כמה traces איטיים מחלון הזמן הזה', 'למצוא את ה-span שלוקח את הזמן', 'לקרוא את ה-logs של ה-span או הכלי הזה', 'לתקן, ואז לראות שה-metric חוזר לנורמלי'] },
          explain: { en: 'Wide to narrow: metric → trace → span → log. Starting from logs means reading thousands of lines with no idea what you are looking for.', he: 'מהרחב לצר: metric ← trace ← span ← log. מי שמתחיל מה-logs קורא אלפי שורות בלי מושג מה הוא מחפש.' } }
      ]
    },
    {
      id: 'm12l5', minutes: 15,
      title: { en: 'The debugging playbook', he: 'ה-playbook לדיבוג' },
      blocks: [
        { t: 'p', en: 'You now have the tools. This lesson is about **order**: for each kind of problem, which signal you open first and what you look for. A pro does not open everything at once. A pro forms one guess, checks one signal, and moves on.', he: 'עכשיו יש לך את הכלים. השיעור הזה עוסק ב**סדר**: לכל סוג בעיה, איזה אות פותחים קודם ומה מחפשים. מקצוען לא פותח הכול בבת אחת. מקצוען מעלה השערה אחת, בודק אות אחד, וממשיך הלאה.' },
        { t: 'table', head: { en: ['Symptom', 'Open first', 'Look for'], he: ['סימפטום', 'פותחים קודם', 'מה מחפשים'] }, rows: {
          en: [
            ['Slow agent', 'Latency metrics, then a slow trace', 'The longest span in the waterfall.'],
            ['Expensive agent', 'Token metrics, then a costly trace', 'Input tokens growing step by step; number of model calls.'],
            ['Wrong answers', 'The trace of a bad answer', 'Which tool was called, with what arguments, and what came back.'],
            ['Stuck in a loop', 'Traces with many spans', 'The same tool with the same arguments again and again.'],
            ['Intermittent AccessDenied', 'CloudTrail', 'Error code, principal, and the Region that served the call.'],
            ['Throttling', 'Throttle and quota metrics', '`InvocationThrottles`, client errors, estimated quota use, `max_tokens`.']
          ],
          he: [
            ['סוכן איטי', 'Metrics של latency, ואז trace איטי', 'ה-span הכי ארוך ב-waterfall.'],
            ['סוכן יקר', 'Metrics של טוקנים, ואז trace יקר', 'טוקני קלט שגדלים מצעד לצעד; מספר הקריאות למודל.'],
            ['תשובות שגויות', 'ה-trace של תשובה גרועה', 'איזה כלי נקרא, עם אילו ארגומנטים, ומה חזר.'],
            ['תקוע בלולאה', 'Traces עם הרבה spans', 'אותו כלי עם אותם ארגומנטים שוב ושוב.'],
            ['AccessDenied לסירוגין', 'CloudTrail', 'קוד השגיאה, ה-principal, וה-Region ששירת את הקריאה.'],
            ['Throttling', 'Metrics של throttling ו-quota', '`InvocationThrottles`, client errors, ניצול quota מוערך, `max_tokens`.']
          ] } },
        { t: 'h', en: '1. The agent is slow', he: '1. הסוכן איטי' },
        { t: 'list', en: [
          '**Start with metrics.** Compare Runtime `Latency` with `OverheadLatency`, and compare both with Bedrock `InvocationLatency`. This tells you which layer grew: the platform, the model, or everything around the model.',
          '**Open a slow trace** and find the longest bar. Typical findings: one slow tool; many model calls in a row; tools called one after another when they could run in parallel.',
          '**A long model span** is often not a slow model but a **long output**. Check the output tokens. Output is written token by token, so 2,000 output tokens take long on any model.',
          '**Hidden retries.** The SDK retries throttled calls quietly. The user only feels the wait. Check `InvocationThrottles` for the same time window.',
          '**Is it the first request of a session only?** Then look at session start-up, not at the agent logic.'
        ], he: [
          '**מתחילים מ-metrics.** משווים `Latency` של Runtime ל-`OverheadLatency`, ואת שניהם ל-`InvocationLatency` של Bedrock. זה אומר איזו שכבה גדלה: הפלטפורמה, המודל, או כל מה שמסביב למודל.',
          '**פותחים trace איטי** ומוצאים את הפס הכי ארוך. ממצאים טיפוסיים: כלי איטי אחד; הרבה קריאות למודל ברצף; כלים שנקראים אחד אחרי השני כשאפשר להריץ אותם במקביל.',
          '**Span ארוך של מודל** הוא לעיתים קרובות לא מודל איטי אלא **פלט ארוך**. בודקים את טוקני הפלט. פלט נכתב טוקן אחרי טוקן, ולכן 2,000 טוקני פלט לוקחים זמן בכל מודל.',
          '**Retries נסתרים.** ה-SDK עושה retry לקריאות שקיבלו throttling בשקט. המשתמש מרגיש רק את ההמתנה. בודקים `InvocationThrottles` לאותו חלון זמן.',
          '**האם זו רק הבקשה הראשונה של session?** אז מסתכלים על עליית ה-session, לא על לוגיקת הסוכן.'
        ] },
        { t: 'quiz', q: { en: 'Runtime `Latency` p95 went from 5 s to 14 s. `OverheadLatency` did not change, and Bedrock `InvocationLatency` did not change. Where is the extra time most likely?', he: '`Latency` של Runtime ב-p95 עלה מ-5 שניות ל-14 שניות. `OverheadLatency` לא השתנה, ו-`InvocationLatency` של Bedrock לא השתנה. איפה כנראה הזמן הנוסף?' },
          options: { en: ['In tool calls or in more loop steps: something the agent does around the model', 'In the AgentCore platform itself', 'In each single model call', 'In CloudTrail delivery'], he: ['בקריאות לכלים או ביותר צעדי לולאה: משהו שהסוכן עושה סביב המודל', 'בפלטפורמת AgentCore עצמה', 'בכל קריאה בודדת למודל', 'במסירה של CloudTrail'] },
          answer: 0, explain: { en: 'Platform overhead is flat and each model call is as fast as before, so the growth is in what the agent does between and around them: a slower tool, or more steps per request. A trace will show which. CloudTrail is never on the request path.', he: 'התקורה של הפלטפורמה שטוחה וכל קריאה למודל מהירה כמו קודם, ולכן הגידול הוא במה שהסוכן עושה ביניהן וסביבן: כלי איטי יותר, או יותר צעדים לבקשה. Trace יראה מה מהשניים. CloudTrail אף פעם לא נמצא במסלול הבקשה.' } },
        { t: 'h', en: '2. The agent is expensive', he: '2. הסוכן יקר' },
        { t: 'list', en: [
          '**Start with tokens per request**, not total tokens. Total tokens grow with traffic; tokens per request grow only when something is wrong.',
          '**Open a costly trace and read the input tokens of each model span in order.** If they go 2,000 → 9,000 → 21,000 → 40,000, the history is snowballing: each step sends everything again plus a big tool result.',
          '**Look at tool results.** A tool that returns a full 50 KB JSON when the agent needed two fields is the number one cause.',
          '**Check prompt caching.** If you added cache checkpoints but `CacheReadInputTokenCount` stays at zero, the cache is not being hit.',
          '**Check who.** Use the cost-per-tenant query: sometimes one tenant or one feature is 70% of the bill.',
          '**Do not forget compute.** `CPUUsed-vCPUHours` and `MemoryUsed-GBHours` show the Runtime side: sessions that stay alive for hours cost memory the whole time.'
        ], he: [
          '**מתחילים מטוקנים לבקשה**, לא מסך הטוקנים. סך הטוקנים גדל עם התעבורה; טוקנים לבקשה גדלים רק כשמשהו לא בסדר.',
          '**פותחים trace יקר וקוראים את טוקני הקלט של כל span מודל לפי הסדר.** אם הם הולכים 2,000 ← 9,000 ← 21,000 ← 40,000, ההיסטוריה מתגלגלת ככדור שלג: כל צעד שולח הכול מחדש ועוד תוצאת כלי גדולה.',
          '**מסתכלים על תוצאות הכלים.** כלי שמחזיר JSON מלא של 50 KB כשהסוכן היה צריך שני שדות הוא הסיבה מספר אחת.',
          '**בודקים prompt caching.** אם הוספת cache checkpoints אבל `CacheReadInputTokenCount` נשאר אפס, ה-cache לא נפגע.',
          '**בודקים מי.** משתמשים בשאילתת העלות לפי tenant: לפעמים tenant אחד או פיצ׳ר אחד הם 70% מהחשבון.',
          '**לא שוכחים את החישוב.** `CPUUsed-vCPUHours` ו-`MemoryUsed-GBHours` מראים את הצד של Runtime: sessions שנשארים חיים שעות עולים זיכרון כל הזמן.'
        ] },
        { t: 'h', en: '3. The agent gives wrong answers', he: '3. הסוכן נותן תשובות שגויות' },
        { t: 'p', en: 'Do not start by changing the prompt. First find out **which kind** of wrong it is. Open the trace of one bad answer and walk through it.', he: 'לא מתחילים משינוי הפרומפט. קודם מבררים **איזה סוג** של טעות זו. פותחים את ה-trace של תשובה גרועה אחת ועוברים עליו.' },
        { t: 'table', head: { en: ['What the trace shows', 'Real cause', 'Fix'], he: ['מה ה-trace מראה', 'הסיבה האמיתית', 'תיקון'] }, rows: {
          en: [
            ['No tool was called; the model answered from its own head', 'The model did not know it should use the tool', 'Better tool description or system prompt'],
            ['The right tool, wrong arguments', 'Unclear parameter schema', 'Fix the tool schema and parameter descriptions'],
            ['The tool returned an error and the model wrote around it', 'A silent tool failure', 'Fix the tool; make the agent say "I could not check"'],
            ['The retrieval returned the wrong documents', 'A RAG problem, not a model problem', 'Chunking, query, filters'],
            ['The context was correct and the answer is still wrong', 'A model or prompt problem', 'Prompt, examples, or a stronger model']
          ],
          he: [
            ['לא נקרא שום כלי; המודל ענה מהראש', 'המודל לא ידע שהוא צריך להשתמש בכלי', 'תיאור כלי או system prompt טובים יותר'],
            ['הכלי הנכון, ארגומנטים שגויים', 'סכמת פרמטרים לא ברורה', 'לתקן את סכמת הכלי ותיאורי הפרמטרים'],
            ['הכלי החזיר שגיאה והמודל כתב מסביב לה', 'כישלון כלי שקט', 'לתקן את הכלי; לגרום לסוכן להגיד "לא הצלחתי לבדוק"'],
            ['האחזור החזיר את המסמכים הלא נכונים', 'בעיית RAG, לא בעיית מודל', 'Chunking, שאילתה, פילטרים'],
            ['ההקשר היה נכון והתשובה עדיין שגויה', 'בעיית מודל או פרומפט', 'פרומפט, דוגמאות, או מודל חזק יותר']
          ] } },
        { t: 'p', en: 'One trace is an anecdote. To know how **often** answers are bad, you need scores on many traces. That is what AgentCore Evaluations does on sampled production traffic: its results are linked to the trace and shown in the Evaluations tab of the agent. Use the scores to find bad sessions, and traces to understand them. If you need the exact prompt text of a model call, the [[Model invocation logging|invocation log]] has it.', he: 'Trace אחד הוא אנקדוטה. כדי לדעת **כמה פעמים** התשובות גרועות, צריך ציונים על הרבה traces. זה מה ש-AgentCore Evaluations עושה על מדגם מתעבורת הפרודקשן: התוצאות שלו מקושרות ל-trace ומוצגות בלשונית Evaluations של הסוכן. משתמשים בציונים כדי למצוא sessions גרועים, וב-traces כדי להבין אותם. אם צריך את טקסט הפרומפט המדויק של קריאה למודל, הוא נמצא ב-[[Model invocation logging|invocation log]].' },
        { t: 'quiz', q: { en: 'A user got "Your order has shipped" for an order that does not exist. In the trace, the span of the `get_order` tool shows an error "404 not found", and the next model span writes the answer. What kind of problem is this?', he: 'משתמש קיבל "ההזמנה שלך נשלחה" על הזמנה שלא קיימת. ב-trace, ה-span של הכלי `get_order` מראה שגיאה "404 not found", וה-span הבא של המודל כותב את התשובה. איזה סוג בעיה זו?' },
          options: { en: ['A retrieval (RAG) problem', 'A silent tool failure that the model covered with a guess', 'A throttling problem', 'A knowledge cutoff problem'], he: ['בעיית אחזור (RAG)', 'כישלון כלי שקט שהמודל כיסה עליו בניחוש', 'בעיית throttling', 'בעיית knowledge cutoff'] },
          answer: 1, explain: { en: 'The tool failed and the model, which always answers, invented a plausible result. The fix is in two places: the tool should return a clear, structured error, and the system prompt should tell the agent to report that it could not find the order.', he: 'הכלי נכשל והמודל, שתמיד עונה, המציא תוצאה שנשמעת סבירה. התיקון הוא בשני מקומות: הכלי צריך להחזיר שגיאה ברורה ומובנית, וה-system prompt צריך להורות לסוכן לדווח שהוא לא מצא את ההזמנה.' } },
        { t: 'h', en: '4. The agent is stuck in a loop', he: '4. הסוכן תקוע בלולאה' },
        { t: 'p', en: 'A loop looks like this in the Traces view: one trace with dozens of spans, a long duration and a huge token count. Inside, the same tool is called with the same arguments again and again. The usual cause is a tool that fails or returns something the model does not understand, so the model tries once more. With the AgentCore harness you set hard limits such as `maxIterations` and `timeoutSeconds`, and a stopped run reports the stop reason `max_iterations_exceeded` or `timeout_exceeded`. In your own agent code, set the same kind of limits in your framework.', he: 'לולאה נראית כך בתצוגת Traces: trace אחד עם עשרות spans, משך ארוך ומספר טוקנים ענק. בפנים, אותו כלי נקרא עם אותם ארגומנטים שוב ושוב. הסיבה הרגילה היא כלי שנכשל או שמחזיר משהו שהמודל לא מבין, ולכן המודל מנסה עוד פעם. ב-harness של AgentCore מגדירים גבולות קשיחים כמו `maxIterations` ו-`timeoutSeconds`, וריצה שנעצרה מדווחת stop reason בשם `max_iterations_exceeded` או `timeout_exceeded`. בקוד סוכן משלך, מגדירים גבולות מאותו סוג ב-framework.' },
        { t: 'order', prompt: { en: 'A trace has 40 spans and cost $1.90. Put the investigation in order.', he: 'ב-trace יש 40 spans והוא עלה $1.90. סדר את החקירה.' }, items: { en: ['Open the trace and group the spans by tool name', 'See that one tool was called 17 times with the same arguments', 'Read the output of that tool span: an unclear error text', 'Fix the tool to return a clear error the model can act on', 'Add or lower the maximum number of iterations as a safety net', 'Add an alarm on spans per trace or on cost per request'], he: ['לפתוח את ה-trace ולקבץ את ה-spans לפי שם הכלי', 'לראות שכלי אחד נקרא 17 פעמים עם אותם ארגומנטים', 'לקרוא את הפלט של ה-span של הכלי: טקסט שגיאה לא ברור', 'לתקן את הכלי כך שיחזיר שגיאה ברורה שהמודל יכול לפעול לפיה', 'להוסיף או להוריד את מספר האיטרציות המקסימלי כרשת ביטחון', 'להוסיף alarm על מספר spans ל-trace או על עלות לבקשה'] },
          explain: { en: 'Find the repeat, find why it repeats, fix the cause, then add the limit and the alarm. The iteration limit alone only hides the bug: the user still gets no answer.', he: 'מוצאים את החזרה, מוצאים למה היא חוזרת, מתקנים את הסיבה, ואז מוסיפים את הגבול ואת ה-alarm. גבול האיטרציות לבדו רק מסתיר את הבאג: המשתמש עדיין לא מקבל תשובה.' } },
        { t: 'h', en: '5. AccessDenied, but only sometimes', he: '5. AccessDenied, אבל רק לפעמים' },
        { t: 'p', en: 'A permission error that happens on 1 request in 3 confuses people, because IAM is not random. The usual explanation is that **the requests are not really the same**. This is a job for [[CloudTrail]], because CloudTrail shows the principal, the error and where the call went.', he: 'שגיאת הרשאה שקורית בבקשה אחת מתוך 3 מבלבלת אנשים, כי IAM לא אקראי. ההסבר הרגיל הוא ש**הבקשות לא באמת זהות**. זו עבודה ל-[[CloudTrail]], כי CloudTrail מראה את ה-principal, את השגיאה ולאן הקריאה הלכה.' },
        { t: 'list', en: [
          '**Cross-Region inference.** With an inference profile, a request can run in any of several Regions. The IAM policy must allow the profile **and** the foundation model in **every** destination Region. If one Region is missing, only the requests routed there fail. In CloudTrail compare `additionalEventData.inferenceRegion` of failed and successful calls.',
          '**A Region-deny rule in the organization (SCP)** that blocks one of the destination Regions gives the same pattern.',
          '**Different callers.** Two services or two roles call the same model, and only one of the roles has the permission. Compare the principal ARN of failed and successful events.',
          '**A guardrail-enforcing role.** A role that is forced to always send a specific guardrail cannot be reused for `RetrieveAndGenerate` or `InvokeAgent`: those calls get access denied.'
        ], he: [
          '**Cross-Region inference.** עם inference profile, בקשה יכולה לרוץ בכל אחד מכמה Regions. ה-IAM policy חייבת לאפשר את ה-profile **וגם** את ה-foundation model ב**כל** Region יעד. אם Region אחד חסר, רק הבקשות שנותבו אליו נכשלות. ב-CloudTrail משווים את `additionalEventData.inferenceRegion` של קריאות שנכשלו ושל קריאות שהצליחו.',
          '**כלל חסימת Regions בארגון (SCP)** שחוסם את אחד מ-Regions היעד נותן את אותו דפוס.',
          '**קוראים שונים.** שני שירותים או שני roles קוראים לאותו מודל, ורק לאחד מה-roles יש את ההרשאה. משווים את ה-ARN של ה-principal באירועים שנכשלו ושהצליחו.',
          '**Role שאוכף guardrail.** Role שמחויב לשלוח תמיד guardrail מסוים לא יכול לשמש גם ל-`RetrieveAndGenerate` או `InvokeAgent`: הקריאות האלה מקבלות access denied.'
        ] },
        { t: 'quiz', q: { en: 'Your service calls `us.anthropic...` (a US cross-Region inference profile) from us-east-1. About one call in three fails with AccessDenied. The IAM policy allows the inference profile and the foundation model in us-east-1 and us-east-2. What do you check in CloudTrail?', he: 'השירות שלך קורא ל-`us.anthropic...` (US cross-Region inference profile) מ-us-east-1. בערך קריאה אחת מתוך שלוש נכשלת עם AccessDenied. ה-IAM policy מאפשרת את ה-inference profile ואת ה-foundation model ב-us-east-1 וב-us-east-2. מה בודקים ב-CloudTrail?' },
          options: { en: ['The prompt text of the failed calls', 'The output token count of the failed calls', 'The `inferenceRegion` of the calls: the profile probably also routes to a Region that the policy does not list', 'Whether data events are enabled for guardrails'], he: ['את טקסט הפרומפט של הקריאות שנכשלו', 'את מספר טוקני הפלט של הקריאות שנכשלו', 'את ה-`inferenceRegion` של הקריאות: ה-profile כנראה מנתב גם ל-Region שה-policy לא מזכירה', 'האם data events מופעלים ל-guardrails'] },
          answer: 2, explain: { en: 'A US profile can route to more Regions than the two in the policy (for example us-west-2). Requests routed there are denied. The fix is to allow the foundation-model ARN in every destination Region of the profile. CloudTrail never contains the prompt text.', he: 'US profile יכול לנתב ליותר Regions מהשניים שב-policy (למשל us-west-2). בקשות שמנותבות לשם נדחות. התיקון הוא לאפשר את ה-ARN של ה-foundation model בכל Region יעד של ה-profile. CloudTrail אף פעם לא מכיל את טקסט הפרומפט.' } },
        { t: 'h', en: '6. Throttling', he: '6. Throttling' },
        { t: 'list', en: [
          '**Confirm it.** Bedrock: `InvocationThrottles`, and also `InvocationClientErrors` (quota-exceeded rejections land there). Runtime: the `Throttles` metric, which counts 429 responses.',
          '**Know which error you have.** `ThrottlingException` (HTTP 429) means **your** quota was exceeded. `ServiceUnavailable` (503) means service capacity, not your quota. The fixes differ.',
          '**Check `max_tokens`.** The quota check at the start of a request reserves input tokens + `max_tokens`. A request with `max_tokens` of 32,000 that writes 200 tokens still blocks a large part of your quota while it runs.',
          '**Remember the burndown rate.** For some models each output token counts as several tokens against the quota. A workload with long outputs hits the quota much sooner than the raw token count suggests.',
          '**Look for bursts.** A per-minute quota can be fine on average and still be exceeded for 10 seconds when a batch job starts.'
        ], he: [
          '**מאשרים שזה באמת זה.** ב-Bedrock: `InvocationThrottles`, וגם `InvocationClientErrors` (דחיות בגלל חריגה מ-quota נוחתות שם). ב-Runtime: ה-metric בשם `Throttles`, שסופר תשובות 429.',
          '**יודעים איזו שגיאה יש לך.** `ThrottlingException` (HTTP 429) אומר שה-quota **שלך** נחצה. `ServiceUnavailable` (503) אומר קיבולת של השירות, לא ה-quota שלך. התיקונים שונים.',
          '**בודקים `max_tokens`.** בדיקת ה-quota בתחילת בקשה שומרת טוקני קלט + `max_tokens`. בקשה עם `max_tokens` של 32,000 שכותבת 200 טוקנים עדיין חוסמת חלק גדול מה-quota שלך בזמן שהיא רצה.',
          '**זוכרים את ה-burndown rate.** בחלק מהמודלים כל טוקן פלט נספר ככמה טוקנים מול ה-quota. עומס עם פלטים ארוכים מגיע ל-quota הרבה יותר מוקדם ממה שספירת הטוקנים הגולמית מרמזת.',
          '**מחפשים פרצים.** Quota לדקה יכול להיות בסדר בממוצע ועדיין להיחצות ל-10 שניות כשמתחיל batch job.'
        ] },
        { t: 'match', prompt: { en: 'Match the symptom to the first thing you open.', he: 'התאם את הסימפטום לדבר הראשון שפותחים.' }, pairs: [
          { a: { en: 'p95 latency doubled since noon', he: 'ה-latency ב-p95 הוכפל מאז הצהריים' }, b: { en: 'Latency metrics, then the waterfall of a slow trace', he: 'Metrics של latency, ואז ה-waterfall של trace איטי' } },
          { a: { en: 'The bill doubled but traffic did not', he: 'החשבון הוכפל אבל התעבורה לא' }, b: { en: 'Tokens per request, then input tokens span by span', he: 'טוקנים לבקשה, ואז טוקני קלט span אחרי span' } },
          { a: { en: 'One user reports a made-up refund policy', he: 'משתמש אחד מדווח על מדיניות החזרים מומצאת' }, b: { en: 'That session\'s trace: retrieval and tool spans', he: 'ה-trace של ה-session הזה: spans של אחזור וכלים' } },
          { a: { en: 'AccessDenied on some calls only', he: 'AccessDenied רק בחלק מהקריאות' }, b: { en: 'CloudTrail: principal and inferenceRegion', he: 'CloudTrail: ה-principal וה-inferenceRegion' } },
          { a: { en: 'HTTP 429 during the morning peak', he: 'HTTP 429 בשיא של הבוקר' }, b: { en: 'Throttle and quota metrics, and max_tokens', he: 'Metrics של throttling ו-quota, ו-max_tokens' } }
        ] },
        { t: 'quiz', q: { en: 'A job sends 50 requests at once. Each has 1,000 input tokens and `max_tokens` = 16,000, but real answers are about 300 tokens. Many requests are throttled although the dashboard shows low real token usage. What is the cheapest fix?', he: 'Job שולח 50 בקשות בבת אחת. בכל אחת 1,000 טוקני קלט ו-`max_tokens` = 16,000, אבל התשובות האמיתיות הן בערך 300 טוקנים. הרבה בקשות מקבלות throttling למרות שהדשבורד מראה ניצול טוקנים אמיתי נמוך. מה התיקון הזול ביותר?' },
          options: { en: ['Switch to a bigger model', 'Turn off streaming', 'Enable CloudTrail data events', 'Lower `max_tokens` to a realistic value such as 500'], he: ['לעבור למודל גדול יותר', 'לכבות streaming', 'להפעיל data events ב-CloudTrail', 'להוריד את `max_tokens` לערך ריאלי כמו 500'] },
          answer: 3, explain: { en: 'At request start the quota is charged input + `max_tokens`: 17,000 per request, 850,000 for 50 at once. With `max_tokens` = 500 the reservation is 1,500 each, 75,000 in total. Same work, more than 10 times less quota pressure, and no cost.', he: 'בתחילת הבקשה ה-quota מחויב בקלט + `max_tokens`: 17,000 לבקשה, 850,000 ל-50 בבת אחת. עם `max_tokens` = 500 השמירה היא 1,500 לכל אחת, 75,000 בסך הכול. אותה עבודה, יותר מפי 10 פחות לחץ על ה-quota, ובלי עלות.' } },
        { t: 'h', en: 'Privacy: your logs are now full of user data', he: 'פרטיות: ה-logs שלך מלאים עכשיו במידע של משתמשים' },
        { t: 'p', en: 'Everything in this module has a price that is not money. Prompts contain what users typed: names, emails, order numbers, health questions, sometimes passwords pasted by mistake. This is [[PII]]. Once you turn on invocation logging and tracing, that data is copied into log groups and buckets. Know exactly where:', he: 'לכל מה שבמודול הזה יש מחיר שהוא לא כסף. פרומפטים מכילים מה שמשתמשים הקלידו: שמות, אימיילים, מספרי הזמנה, שאלות על בריאות, לפעמים סיסמאות שהודבקו בטעות. זה [[PII]]. ברגע שמדליקים invocation logging ו-tracing, המידע הזה מועתק ל-log groups ול-buckets. חשוב לדעת בדיוק לאן:' },
        { t: 'list', en: [
          '**Model invocation logs** hold the full prompt and answer. They keep the **original** input even when a guardrail masked it for the user.',
          '**Guardrail traces** hold the unmasked matched value.',
          '**Runtime `APPLICATION_LOGS`** include the request payload.',
          '**Spans** can include prompts, tool arguments and tool results, depending on your framework and its settings.',
          '**Your own log lines.** A helpful `print(user_message)` is a privacy leak.'
        ], he: [
          '**Model invocation logs** מחזיקים את הפרומפט והתשובה המלאים. הם שומרים את הקלט **המקורי** גם כש-guardrail מיסך אותו עבור המשתמש.',
          '**Traces של guardrail** מחזיקים את הערך שנתפס, לא ממוסך.',
          '**`APPLICATION_LOGS` של Runtime** כוללים את ה-request payload.',
          '**Spans** יכולים לכלול פרומפטים, ארגומנטים של כלים ותוצאות של כלים, תלוי ב-framework ובהגדרות שלו.',
          '**שורות ה-log שלך.** `print(user_message)` שנועד לעזור הוא דליפת פרטיות.'
        ] },
        { t: 'table', head: { en: ['Control', 'What you do'], he: ['בקרה', 'מה עושים'] }, rows: {
          en: [
            ['Minimize', 'Log only the modalities and fields you need. Do not log what you will never read.'],
            ['Mask', 'Remove or mask PII in your application before it is logged, and where possible before it reaches the model. Check the CloudWatch docs for the log masking features available to you.'],
            ['[[Retention]]', 'Set a retention period on every log group and a lifecycle rule on the bucket. "Forever" is the wrong default for user content.'],
            ['Access', 'Only the people who debug may read prompt logs. Give access per log group. Agents with their own log group make this easy.'],
            ['Encrypt', 'Encrypt log groups and buckets, with your own KMS key when the data is sensitive.'],
            ['[[Sampling]]', 'For traces and evaluations, a sample is often enough and stores less user data.'],
            ['Tell users', 'Your privacy policy must match what you really store and for how long.']
          ],
          he: [
            ['לצמצם', 'רושמים רק את ה-modalities והשדות שצריך. לא רושמים מה שלעולם לא תקרא.'],
            ['למסך', 'מסירים או ממסכים PII באפליקציה לפני שהוא נרשם, וכשאפשר לפני שהוא מגיע למודל. בדוק בתיעוד של CloudWatch אילו יכולות מיסוך logs זמינות לך.'],
            ['[[Retention]]', 'קובעים retention לכל log group וכלל lifecycle על ה-bucket. "לנצח" היא ברירת מחדל שגויה לתוכן של משתמשים.'],
            ['גישה', 'רק מי שמדבג רשאי לקרוא logs של פרומפטים. נותנים גישה לפי log group. סוכנים עם log group משלהם מקלים על זה.'],
            ['להצפין', 'מצפינים log groups ו-buckets, עם מפתח KMS משלך כשהמידע רגיש.'],
            ['[[Sampling]]', 'ל-traces ול-evaluations מדגם מספיק לעיתים קרובות ושומר פחות מידע של משתמשים.'],
            ['לספר למשתמשים', 'מדיניות הפרטיות שלך חייבת להתאים למה שאתה באמת שומר ולכמה זמן.']
          ] } },
        { t: 'quiz', q: { en: 'Your guardrail masks credit card numbers in the model\'s answers. A developer says: "So our invocation logs are free of card numbers." Which statements are correct? Pick all that apply.', he: 'ה-guardrail שלך ממסך מספרי כרטיסי אשראי בתשובות של המודל. מפתח אומר: "אז ה-invocation logs שלנו נקיים ממספרי כרטיסים." אילו משפטים נכונים? בחר את כל הנכונים.' },
          options: { en: ['Wrong: invocation logs keep the original input', 'Wrong: the guardrail trace holds the unmasked match', 'Right: masking also rewrites the stored logs', 'Right: CloudTrail removes PII automatically'], he: ['טעות: invocation logs שומרים את הקלט המקורי', 'טעות: ה-trace של ה-guardrail מחזיק את הערך הלא ממוסך', 'נכון: המיסוך משכתב גם את ה-logs השמורים', 'נכון: CloudTrail מסיר PII אוטומטית'] },
          answer: [0, 1], explain: { en: 'Masking changes what the user sees, not what was logged. The invocation log keeps the original input and the guardrail trace keeps the unmasked value. So the log store must be protected as if it holds card numbers, because it does.', he: 'מיסוך משנה מה שהמשתמש רואה, לא מה שנרשם. ה-invocation log שומר את הקלט המקורי וה-trace של ה-guardrail שומר את הערך הלא ממוסך. לכן צריך להגן על מאגר ה-logs כאילו הוא מחזיק מספרי כרטיסים, כי הוא באמת מחזיק.' } },
        { t: 'reveal', q: { en: 'Interview question: "A customer asks us to delete all their data. We have invocation logging and tracing on. What do you need to have in place to do that?"', he: 'שאלת ראיון: "לקוח מבקש שנמחק את כל המידע שלו. יש לנו invocation logging ו-tracing דלוקים. מה צריך שיהיה מוכן כדי לעשות את זה?"' },
          a: { en: 'First, a map of every place where user content lands: invocation logs in CloudWatch and S3, large-data objects in S3, span logs, Runtime application logs, memory records, evaluation results and my own application logs. Second, a way to find one customer\'s data in each place: a tenant or user identifier in request metadata, in span attributes and in the session ID. Third, short retention periods, so most data disappears by itself and deletion requests cover a small window. Without the identifier and the map, I cannot honestly say the data is gone. So I design these before turning the logging on, not after the first request arrives.', he: 'קודם כול, מפה של כל מקום שבו תוכן של משתמשים נוחת: invocation logs ב-CloudWatch וב-S3, אובייקטים של מידע גדול ב-S3, logs של spans, application logs של Runtime, רשומות זיכרון, תוצאות evaluation וה-logs של האפליקציה שלי. שנית, דרך למצוא מידע של לקוח אחד בכל מקום: מזהה tenant או משתמש ב-request metadata, ב-attributes של spans וב-session ID. שלישית, תקופות retention קצרות, כך שרוב המידע נעלם לבד ובקשות מחיקה מכסות חלון קטן. בלי המזהה והמפה, אני לא יכול להגיד ביושר שהמידע נמחק. לכן מתכננים את זה לפני שמדליקים את ה-logging, לא אחרי שהבקשה הראשונה מגיעה.' } }
      ]
    },
    {
      id: 'm12l6', minutes: 10,
      title: { en: 'Jargon and scenarios workout', he: 'אימון ז׳רגון ותרחישים' },
      blocks: [
        { t: 'p', en: 'Time to check that the words and the reflexes are in place. Nothing new here: only practice in the style of real incidents and real interviews.', he: 'הגיע הזמן לבדוק שהמילים והרפלקסים במקום. אין כאן חומר חדש: רק תרגול בסגנון של תקלות אמיתיות וראיונות אמיתיים.' },
        { t: 'match', prompt: { en: 'Match the term to its meaning.', he: 'התאם את המונח למשמעות שלו.' }, pairs: [
          { a: 'ADOT', b: { en: 'The AWS-supported OpenTelemetry build', he: 'גרסת OpenTelemetry ש-AWS תומכת בה' } },
          { a: 'Transaction Search', b: { en: 'Stores spans as structured logs so traces can be searched', he: 'שומר spans כ-logs מובנים כדי שאפשר יהיה לחפש ב-traces' } },
          { a: 'Model invocation logging', b: { en: 'Saves the full prompt and answer of model calls', he: 'שומר את הפרומפט והתשובה המלאים של קריאות למודל' } },
          { a: 'CloudTrail', b: { en: 'Audit log of who called which API', he: 'יומן ביקורת של מי קרא לאיזה API' } },
          { a: 'p95', b: { en: 'The value 95% of requests are faster than', he: 'הערך ש-95% מהבקשות מהירות ממנו' } },
          { a: 'Baggage', b: { en: 'Carries the session ID along with the request', he: 'נושא את ה-session ID יחד עם הבקשה' } }
        ] },
        { t: 'match', prompt: { en: 'Match the metric to what it tells you.', he: 'התאם את ה-metric למה שהוא מספר לך.' }, pairs: [
          { a: 'TimeToFirstToken', b: { en: 'How long a streaming user waits for the first word', he: 'כמה זמן משתמש streaming מחכה למילה הראשונה' } },
          { a: 'OverheadLatency', b: { en: 'Platform time, without your agent\'s own work', he: 'זמן הפלטפורמה, בלי העבודה של הסוכן עצמו' } },
          { a: 'InvocationsIntervened', b: { en: 'How often a guardrail stepped in', he: 'כמה פעמים guardrail התערב' } },
          { a: 'CacheReadInputTokenCount', b: { en: 'Whether prompt caching is really being hit', he: 'האם prompt caching באמת נפגע' } },
          { a: 'EstimatedTPMQuotaUsage', b: { en: 'How close you are to the tokens-per-minute quota (roughly)', he: 'כמה אתה קרוב ל-quota של טוקנים לדקה (בערך)' } },
          { a: 'ActiveSessionCount', b: { en: 'How many agent sessions are running now', he: 'כמה sessions של סוכנים רצים עכשיו' } }
        ] },
        { t: 'quiz', q: { en: 'You moved an agent from Runtime to an EKS cluster and copied the ADOT environment variables. Traces arrive, but the Sessions view shows each turn as a separate one-trace session. What did you forget?', he: 'העברת סוכן מ-Runtime ל-EKS cluster והעתקת את משתני הסביבה של ADOT. Traces מגיעים, אבל תצוגת Sessions מראה כל תור כ-session נפרד עם trace אחד. מה שכחת?' },
          options: { en: ['To set the session ID in OpenTelemetry baggage', 'To enable model invocation logging', 'To create an application inference profile', 'To enable CloudTrail data events'], he: ['לקבוע את ה-session ID ב-baggage של OpenTelemetry', 'להפעיל model invocation logging', 'ליצור application inference profile', 'להפעיל data events ב-CloudTrail'] },
          answer: 0, explain: { en: 'On Runtime the platform knows the session. Outside it you must propagate it yourself with `baggage.set_baggage("session.id", session_id)`. Without it, traces cannot be grouped into conversations.', he: 'ב-Runtime הפלטפורמה מכירה את ה-session. מחוץ לו צריך להעביר אותו לבד עם `baggage.set_baggage("session.id", session_id)`. בלי זה אי אפשר לקבץ traces לשיחות.' } },
        { t: 'quiz', q: { en: 'You count Bedrock calls from CloudTrail for an audit and get almost exactly twice the number that the `Invocations` metric shows. Most of your calls use `ConverseStream`. Why?', he: 'אתה סופר קריאות Bedrock מ-CloudTrail בשביל ביקורת ומקבל כמעט בדיוק פי שניים מהמספר שה-metric בשם `Invocations` מראה. רוב הקריאות שלך משתמשות ב-`ConverseStream`. למה?' },
          options: { en: ['CloudTrail also counts throttled calls twice', 'Streaming calls create a second event of type AwsServiceEvent when the stream ends', 'The metric only counts calls with a guardrail', 'CloudTrail logs every token as an event'], he: ['CloudTrail סופר גם קריאות עם throttling פעמיים', 'קריאות streaming יוצרות אירוע שני מסוג AwsServiceEvent כשה-stream נגמר', 'ה-metric סופר רק קריאות עם guardrail', 'CloudTrail רושם כל טוקן כאירוע'] },
          answer: 1, explain: { en: 'Each streaming call produces the API call event and, after the stream ends, a second event with the same name and `eventType` = `AwsServiceEvent` that carries the token counts. Count only `eventType = AwsApiCall`.', he: 'כל קריאת streaming מייצרת את אירוע קריאת ה-API, ואחרי שה-stream נגמר, אירוע שני עם אותו שם ו-`eventType` = `AwsServiceEvent` שנושא את ספירות הטוקנים. סופרים רק `eventType = AwsApiCall`.' } },
        { t: 'quiz', q: { en: 'A new teammate wants to "just add print statements" to understand why an agent sometimes takes 40 seconds. What do you tell them?', he: 'חבר צוות חדש רוצה "פשוט להוסיף print" כדי להבין למה סוכן לפעמים לוקח 40 שניות. מה אתה אומר לו?' },
          options: { en: ['Good idea, logs are the best signal for timing', 'Raise the model temperature first', 'Open a slow trace: the span waterfall already shows which step took the time, with no code change', 'Turn on CloudTrail data events and read them'], he: ['רעיון טוב, logs הם האות הכי טוב לתזמון', 'קודם להעלות את ה-temperature של המודל', 'לפתוח trace איטי: ה-waterfall של ה-spans כבר מראה איזה שלב לקח את הזמן, בלי שינוי קוד', 'להדליק data events ב-CloudTrail ולקרוא אותם'] },
          answer: 2, explain: { en: 'Timing across steps is exactly what traces are for. Print statements need a deploy, mix lines from many requests, and may leak user data into logs. Logs become useful after the trace has pointed at one span.', he: 'תזמון בין שלבים הוא בדיוק מה ש-traces נועדו לו. Print דורש deploy, מערבב שורות מהרבה בקשות, ועלול להדליף מידע של משתמשים ל-logs. Logs נהיים שימושיים אחרי שה-trace הצביע על span אחד.' } },
        { t: 'quiz', q: { en: 'Which setup gives you the exact prompt text for a bad answer from last Tuesday?', he: 'איזו הגדרה נותנת לך את טקסט הפרומפט המדויק של תשובה גרועה מיום שלישי שעבר?' },
          options: { en: ['CloudTrail management events', 'The AWS/Bedrock CloudWatch metrics', 'A CloudWatch alarm history', 'Model invocation logging that was enabled before Tuesday, with enough retention'], he: ['Management events של CloudTrail', 'ה-CloudWatch metrics ב-AWS/Bedrock', 'היסטוריה של CloudWatch alarm', 'Model invocation logging שהופעל לפני יום שלישי, עם retention מספיק'] },
          answer: 3, explain: { en: 'Only invocation logs (or spans that record content) hold the prompt, and only if they were on at the time and have not expired. Metrics are numbers and CloudTrail records the call without the content. You cannot turn logging on afterwards.', he: 'רק invocation logs (או spans שרושמים תוכן) מחזיקים את הפרומפט, ורק אם הם היו דלוקים באותו זמן ולא פג תוקפם. Metrics הם מספרים ו-CloudTrail רושם את הקריאה בלי התוכן. אי אפשר להדליק logging בדיעבד.' } },
        { t: 'reveal', q: { en: 'Interview: "Walk me through how you would set up observability for a new customer-facing agent on AgentCore, from zero."', he: 'ראיון: "תעביר אותי על איך היית מקים observability לסוכן חדש מול לקוחות על AgentCore, מאפס."' },
          a: { en: 'Account level, once: enable CloudWatch Transaction Search so spans are stored. Agent: add the ADOT distro and start through opentelemetry-instrument, so model and tool calls become spans with GenAI attributes. Managed parts: enable Tracing and Log delivery on Gateway and Memory. Models: decide on model invocation logging per Region, with access control and retention. Then the day-one dashboard: latency p50 and p95 for agent and model, time to first token, error and throttle rates, tokens per request, cost by feature using application inference profiles or request metadata, guardrail intervention rate, tool failure rate, active sessions. Alarms on rates and percentiles, held for several periods. Online evaluations on a sample for quality. Finally privacy: know where prompts are stored, who can read them and when they expire.', he: 'ברמת החשבון, פעם אחת: להפעיל CloudWatch Transaction Search כדי ש-spans יישמרו. הסוכן: להוסיף את ADOT ולהפעיל דרך opentelemetry-instrument, כך שקריאות למודל ולכלים הופכות ל-spans עם GenAI attributes. החלקים המנוהלים: להפעיל Tracing ו-Log delivery על Gateway ו-Memory. מודלים: להחליט על model invocation logging לכל Region, עם בקרת גישה ו-retention. אחר כך הדשבורד של היום הראשון: latency ב-p50 ו-p95 לסוכן ולמודל, הזמן עד הטוקן הראשון, שיעורי שגיאות ו-throttling, טוקנים לבקשה, עלות לפי פיצ׳ר עם application inference profiles או request metadata, שיעור התערבות guardrail, שיעור כישלון כלים, sessions פעילים. Alarms על שיעורים ו-percentiles, שמתקיימים כמה פרקי זמן. Online evaluations על מדגם בשביל איכות. ולבסוף פרטיות: לדעת איפה פרומפטים נשמרים, מי יכול לקרוא אותם ומתי הם פגים.' } },
        { t: 'reveal', q: { en: 'Interview: "What is the difference between metrics, logs and traces? Give an agent example for each."', he: 'ראיון: "מה ההבדל בין metrics, logs ו-traces? תן דוגמה מסוכן לכל אחד."' },
          a: { en: 'A metric is a number over time across all traffic: p95 agent latency per 5 minutes. It tells me that something is wrong and since when. A trace is the path of one request: this turn made three model calls and two tool calls, and the second tool took 4 of the 6 seconds. It tells me where. A log is the detail of one event: the tool\'s error line "upstream timeout after 3000 ms". It tells me why. I move from metric to trace to log.', he: 'Metric הוא מספר לאורך זמן על כל התעבורה: latency של הסוכן ב-p95 לכל 5 דקות. הוא אומר לי שמשהו לא בסדר וממתי. Trace הוא המסלול של בקשה אחת: התור הזה עשה שלוש קריאות למודל ושתי קריאות לכלים, והכלי השני לקח 4 מתוך 6 השניות. הוא אומר לי איפה. Log הוא הפרט של אירוע אחד: שורת השגיאה של הכלי "upstream timeout after 3000 ms". הוא אומר לי למה. אני עובר מ-metric ל-trace ל-log.' } },
        { t: 'reveal', q: { en: 'Interview: "Our Bedrock bill tripled this month. You have one hour. What do you do?"', he: 'ראיון: "חשבון ה-Bedrock שלנו שילש את עצמו החודש. יש לך שעה. מה אתה עושה?"' },
          a: { en: 'First split the problem: did traffic triple, or did cost per request triple? I compare `Invocations` with `InputTokenCount` and `OutputTokenCount` over the month. If tokens per request jumped on a certain date, I look for what was deployed that day. Then I find who: Cost Explorer by application inference profile tag, or a Logs Insights query on invocation logs grouped by request metadata or `identity.arn`. Then I open the most expensive traces and read input tokens span by span, looking for loops, huge tool results and history growth, and I check whether cache read tokens dropped to zero. The short-term stop is a limit: lower `max_tokens`, an iteration cap, a budget alarm per feature. The real fix depends on what the trace shows.', he: 'קודם מפצלים את הבעיה: האם התעבורה שילשה את עצמה, או העלות לבקשה? משווים `Invocations` ל-`InputTokenCount` ו-`OutputTokenCount` לאורך החודש. אם הטוקנים לבקשה קפצו בתאריך מסוים, מחפשים מה הועלה באותו יום. אחר כך מוצאים מי: Cost Explorer לפי תג של application inference profile, או שאילתת Logs Insights על invocation logs עם קיבוץ לפי request metadata או `identity.arn`. אחר כך פותחים את ה-traces הכי יקרים וקוראים טוקני קלט span אחרי span, מחפשים לולאות, תוצאות כלים ענקיות וגידול בהיסטוריה, ובודקים אם טוקני ה-cache read ירדו לאפס. העצירה לטווח קצר היא גבול: להוריד `max_tokens`, תקרת איטרציות, alarm תקציב לכל פיצ׳ר. התיקון האמיתי תלוי במה שה-trace מראה.' } },
        { t: 'task', title: { en: 'Do it for real (after you land)', he: 'עשה את זה באמת (אחרי שתנחת)' }, steps: {
          en: [
            'Enable CloudWatch Transaction Search in your account.',
            'Deploy a small agent with the AgentCore CLI, invoke it a few times, then run `agentcore logs runtime --since 30m` and `agentcore traces runtime list --since 30m`.',
            'Open CloudWatch → GenAI Observability → Bedrock AgentCore and drill down: agent → session → trace → span.',
            'In the Bedrock console open Settings and turn on model invocation logging to a CloudWatch log group, text only. Set a retention period on the log group.',
            'Call Converse with `requestMetadata`, then write a Logs Insights query that sums tokens by one of your metadata keys.',
            'Open the Model Invocations view in GenAI Observability and find `InvocationLatency` and `InputTokenCount` for your model.',
            'Create one alarm on a rate (errors divided by invocations), not on a count.',
            'When you finish, turn off or delete what you do not need, so that you do not pay for stored logs.'
          ],
          he: [
            'הפעל CloudWatch Transaction Search בחשבון שלך.',
            'העלה סוכן קטן עם AgentCore CLI, קרא לו כמה פעמים, ואז הרץ `agentcore logs runtime --since 30m` ו-`agentcore traces runtime list --since 30m`.',
            'פתח CloudWatch ← GenAI Observability ← Bedrock AgentCore ורד פנימה: agent ← session ← trace ← span.',
            'בקונסול של Bedrock פתח Settings והדלק model invocation logging ל-log group ב-CloudWatch, טקסט בלבד. קבע retention ל-log group.',
            'קרא ל-Converse עם `requestMetadata`, ואז כתוב שאילתת Logs Insights שמסכמת טוקנים לפי אחד ממפתחות ה-metadata שלך.',
            'פתח את התצוגה Model Invocations ב-GenAI Observability ומצא את `InvocationLatency` ו-`InputTokenCount` של המודל שלך.',
            'צור alarm אחד על שיעור (שגיאות חלקי invocations), לא על ספירה.',
            'כשתסיים, כבה או מחק מה שלא צריך, כדי לא לשלם על logs שמורים.'
          ] } }
      ]
    }
  ]
});
